'Custom_SMS_Guide_Title' => 'Yadda ake saitawa',
'Custom_SMS_Guide_Intro' => 'Ana iya haɗa kowane mai samar da SMS da ke da HTTP API. Buɗe takardun API na mai samarwa, kwafi endpoint, method da sunayen filaye, sannan ka haɗa su a ƙasa ta amfani da masu riƙe wuri.',
