'Custom_SMS_Guide_Method' => 'POST ne aka fi amfani da shi. Zaɓi GET kawai idan mai samarwa yana tsammanin komai a cikin URL — sai a aika filayen payload a matsayin query parameters.',
'Custom_SMS_Guide_Content_Type' => '"json" yana aika payload a matsayin jikin JSON (application/json). "form" yana aika shi a matsayin tsohon fom na HTML (application/x-www-form-urlencoded). Duba wanda mai samarwa yake tsammani; ba a amfani da shi don GET.',
'Custom_SMS_Guide_Sender' => 'Sender ID ɗinka da aka amince da shi ko lambar wayar aikawa. Yana cika mai riƙe wurin {sender} ne kawai — don a aika shi dole a yi amfani da shi a cikin payload, headers ko URL.',
'Custom_SMS_Guide_Success_Keyword' => 'Na zaɓi amma ana ba da shawarar sa. Wasu masu samarwa suna amsa "200 OK" ko da aikawa ta kasa. Shigar da kalma ko guntun rubutu da ke bayyana a amsar nasara kawai (misali success). Idan amsar ba ta ƙunshe da shi ba, za a ɗauki SMS ɗin a matsayin wanda ya kasa.',
'Custom_SMS_Guide_Headers' => 'Headers na tantancewa da mai samarwa yake buƙata, misali Authorization = Bearer YOUR_API_KEY, ko Api-Key = YOUR_API_KEY. Kada ka ƙara Content-Type — ana saita shi ta atomatik.',
'Custom_SMS_Guide_Payload' => 'Filayen jikin buƙata, da sunaye daidai kamar a takardun mai samarwa. Yi amfani da masu riƙe wuri a matsayin ƙima, misali to = {phone}, message = {message}, from = {sender}.',
