'Cr_Guide_Step_Account_Help' => 'Zaɓi kamfanin isar da kayanku kuma liƙa maɓallan API daga Dashboard ɗinsa. Asusu da yawa ba matsala ba ne, misali ɗaya ga kowane sito.',
