'Cr_Guide_Step_Cod' => 'Zaɓi inda kuɗin COD za su shiga',
'Cr_Guide_Step_Cod_Help' => 'A Saitunan isar da kaya, zaɓi asusun da za a rubuta kuɗin COD a ciki, da yadda za a kula da kunshin da aka mayar da kuɗin kamfanin isar da kaya.',
'Cr_Guide_Step_Notify' => 'Sanar da abokan cinikinku',
'Cr_Guide_Step_Notify_Help' => 'SMS, imel ko WhatsApp a matsayin da kuka zaɓa, tare da hanyar haɗi zuwa shafin bin diddigi.',
