'Cr_Guide_Step_Book_Help' => 'A jerin siyarwa, buɗe menu na siyarwa ka zaɓi Tura zuwa kamfanin isar da kaya, ko ka zaɓi siyarwa da yawa ka tura su lokaci guda.',
'Cr_Guide_Step_Errors' => 'Ku riƙa lura da kurakurai',
'Cr_Guide_Step_Errors_Help' => 'Babu kurakuran kamfanin isar da kaya a cikin sa’o’i 24 da suka gabata.',
'Cr_Guide_Courier_Setup' => 'Saitin kamfanin isar da kaya',
'Cr_Guide_Pick_Courier' => 'Zaɓi kamfanin isar da kaya don ganin abin da yake buƙata',
'Cr_Guide_Add_This' => 'Ƙara wannan kamfanin isar da kaya',
'Cr_Guide_You_Need' => 'Kuna buƙatar',
'Cr_Guide_No_Keys' => 'Babu maɓallan API: babu abin da za a haɗa.',
'Cr_Guide_Good_To_Know' => 'Abin da ya kamata ku sani',
'Cr_Guide_Webhooks' => 'Adiresoshin webhook',
'Cr_Guide_How' => 'Yadda ake yin rajistarsa',
'Cr_Guide_How_It_Works' => 'Yadda yake aiki',
'Cr_Guide_Meaning' => 'Ma’ana',
'Cr_Guide_T_Statuses' => 'Matsayoyi',
'Cr_Guide_Statuses_Note' => 'Matsayi yana ci gaba ne kawai, don haka sabuntawar da ta makara ba za ta taɓa mayar da kunshi baya ba. Har yanzu ana iya bayar da rahoton kunshin da aka isar a matsayin ana dawo da shi ko an dawo da shi.',
'Cr_Guide_S_booked' => 'Kamfanin isar da kaya ya karɓi odar; babu wanda ya ɗauke ta tukuna. A wannan matakin ne kawai za a iya soke booking.',
'Cr_Guide_S_picked_up' => 'Kamfanin isar da kaya ya ɗauki kunshin.',
'Cr_Guide_S_in_transit' => 'Yana tafiya tsakanin cibiyoyi, yana kwastam ko an tsare shi.',
'Cr_Guide_S_out_for_delivery' => 'Yana hannun mai kai kaya a yau.',
'Cr_Guide_S_failed_attempt' => 'Ba a gida ba, an ƙi karɓa ko adireshi ba daidai ba. Kamfanin isar da kaya zai sake gwadawa ko ya mayar da shi.',
'Cr_Guide_S_delivered' => 'An miƙa wa abokin ciniki. Adadin COD ya zama wanda kamfanin isar da kaya ya karɓa.',
'Cr_Guide_S_returning' => 'Yana kan hanyarsa ta dawowa gare ku.',
'Cr_Guide_S_returned' => 'Ya dawo gare ku: yana jira a Mayarwa da za a duba, ko kuma ana mayar da shi cikin ajiyar kaya ta atomatik.',
'Cr_Guide_S_cancelled' => 'An soke booking ɗin.',
'Cr_Guide_T_Booking' => 'Booking na oda',
'Cr_Guide_B_Booking' => 'Tura zuwa kamfanin isar da kaya yana cike fom ɗin daga siyarwar: mai karɓa, adireshi, adadin da ya rage a bashi a matsayin COD, da nauyin kayayyakin. Kamfanonin isar da kaya masu jerin biranensu suna nuna mai zaɓi, kuma ana tuna zaɓinku na wannan birni. Masu haɗa kamfanoni (aggregators), DHL, FedEx, UPS da Lalamove suna ba da Kwatanta farashi: zaɓi farashi, sannan Yi booking yana sayen sa. Ana iya yin booking na siyarwa da yawa lokaci guda daga jerin siyarwa.',
'Cr_Guide_T_Cod' => 'Biya lokacin isarwa',
'Cr_Guide_B_Cod' => 'Kunshin COD yana tafiya daga Ba a karɓa ba zuwa Kamfanin isarwa ya karɓa (lokacin isarwa) zuwa An biya ku. Kamfanonin isar da kaya da ke bayar da rahoton biyan kuɗi suna motsa mataki na ƙarshe da kansu; ga sauran, yi amfani da Sabunta COD. Idan an zaɓi asusu a Saitunan isar da kaya, ana rubuta biyan a matsayin biya a kan siyarwar. Ana iya ajiye kuɗin kamfanin isar da kaya a matsayin kuɗaɗen fita da zarar kunshi ya kammala.',
'Cr_Guide_T_Returns' => 'Kunshin da aka mayar',
'Cr_Guide_B_Returns' => 'A tsarin asali, kunshin da aka mayar yana jira a Jigilar Kaya ƙarƙashin Mayarwa da za a duba. Mayar cikin ajiya yana ƙirƙirar mayarwar siyarwa ta dukan odar kuma yana mayar da kayan cikin ajiyar kaya; Watsar ba ya mayar da komai, don kunshin da ya lalace ko ya ɓace. Saitunan isar da kaya na iya mayar da su cikin ajiya ta atomatik maimakon haka.',
'Cr_Guide_T_Customers' => 'Saƙonnin abokan ciniki da shafin bin diddigi',
'Cr_Guide_B_Customers' => 'Sanarwar abokan ciniki a Saitunan isar da kaya tana aika SMS, imel ko WhatsApp a matsayin da kuka zaɓa, sau ɗaya ga kowane kunshi, da rubutunku. Shafin bin diddigi a shagon yanar gizonku yana bai wa abokan ciniki damar bin kunshi ta lambar bin diddigi, ko ta lambar oda da waya. Abokan cinikin da ke yawan mayar da kunshi suna samun alamar haɗarin mayarwa lokacin da kuka yi booking.',
'Cr_Guide_T_Labels' => 'Lakabi',
'Cr_Guide_B_Labels' => 'Buga lakabi yana ba da lakabin kamfanin isar da kaya na kansa idan ya bayar (PDF, hanyar haɗi ko hoto), in ba haka ba lakabin Stocky mai barcode na bin diddigi da adadin da za a karɓa. Ba da izinin pop-up ga wannan shafin domin bugawa. DHL, FedEx da UPS suna bayar da lakabinsu sau ɗaya kawai, lokacin booking, kuma Stocky yana adana shi don sake bugawa.',
'Cr_Guide_T_Faq' => 'Magance matsaloli',
'Cr_Guide_Q_Test' => 'Gwada Haɗin ya kasa',
'Cr_Guide_A_Test' => 'Maɓallan gwaji suna tafiya da Yanayin gwaji, maɓallan kai tsaye kuma da Kai tsaye; sun bambanta. Buɗe Log ɗin isar da kaya ka karanta amsar kamfanin isar da kaya don ainihin dalili.',
'Cr_Guide_Q_City' => 'Kamfanin isar da kaya ya ƙi birnin ko adireshin',
'Cr_Guide_A_City' => 'Zaɓi birnin daga jerin biranen kamfanin isar da kaya a fom ɗin booking; kamfanonin isar da kaya suna karɓar sunayensu kawai. Kamfanonin da ke aiki da adiresoshin gidan waya suna kuma buƙatar jiha, lambar gidan waya da ƙasa mai haruffa biyu.',
'Cr_Guide_Q_Webhook' => 'Matsayi ba ya canzawa da kansa',
'Cr_Guide_A_Webhook' => 'Ga kamfanonin isar da kaya da ke turo sabuntawa, duba cewa an yi rajistar URL na webhook a wurin kamfanin: Log ɗin isar da kaya yana nuna kowace sabuntawa da aka karɓa, ko dalilin da aka ƙi ta (misali sirri mara daidai). Ana duba sauran kamfanoni bisa jadawalin da ke Saitunan isar da kaya, kuma Duba matsayi yanzu yana tambaya nan take.',
'Cr_Guide_Q_Stuck' => 'Jigila tana nuna kuskuren duba matsayi',
'Cr_Guide_A_Stuck' => 'Kamfanin isar da kaya ya ƙi binciken ƙarshe; dalilin yana kan jigilar da kuma a Log ɗin isar da kaya. Bayan gazawa akai-akai, ba a ƙara duba jigila ta atomatik: gyara dalilin, sannan yi amfani da Duba matsayi yanzu.',
'Cr_Guide_Q_Label' => 'Babu abin da ke buɗewa lokacin buga lakabi',
'Cr_Guide_A_Label' => 'Burauzarku ya toshe pop-up ɗin. Ba da izinin pop-up ga wannan shafin sannan a sake gwadawa.',
'Cr_Guide_Q_Cod' => 'Ba a rubuta biyan COD a kan siyarwar ba',
'Cr_Guide_A_Cod' => 'A Saitunan isar da kaya, biya lokacin isarwa yana buƙatar a kunna maɓallin kuma a zaɓi asusu. Ba tare da asusu ba, ana yi wa biyan alama ne kawai a matsayin an biya.',
