'Restrict_Master_Data_By_Warehouse' => 'Iyakance manyan bayanai bisa sito',
'Restrict_Master_Data_By_Warehouse_Help' => 'Idan an kunna, mai amfani da aka sanya wa takamaiman sitoci yana ganin kayayyaki, abokan ciniki, masu kaya, tambura da rukunonin da aka haɗa da waɗannan sitocin kawai. Bayanan da ba a yi amfani da su a ko’ina ba tukuna suna nan a bayyane, don haka sababbin da aka ƙirƙira ba sa ɓoyewa. Siyarwa, siyan kaya da mayarwa ana iyakance su kullum, kuma wannan maɓallin bai shafe su ba.',
'Restrict_Products_By_Warehouse' => 'Iyakance kayayyaki bisa sito',
'Restrict_Products_By_Warehouse_Help' => 'Kowane kaya yana samun sito na asali — reshen da aka ƙirƙira shi dominsa. Idan an kunna, mai amfani da aka sanya wa takamaiman sitoci yana gani, siyarwa da gyara kayayyakin da sito na asalinsu nasa ne kawai, da kuma kayayyakin da ke da ajiyar kaya ta gaske a ɗaya daga cikin sitocinsa (wanda aka canja wuri ko aka saya zuwa ciki). Masu amfani da za su iya shiga duk sitoci kullum suna ganin komai. Shagon yanar gizo yana bin wannan ƙa’ida: yana jera kayayyakin sitocin da aka zaɓa a Saitunan Shago kawai.',
'Virtual_Combo_Stock' => 'Ajiyar combo ta kama-da-wane',
'Virtual_Combo_Stock_Help' => 'Idan an kunna, kayan combo ba shi da ajiyar kaya ta kansa: samuwarsa ita ce adadin combo da kayan da suka haɗa shi za su iya cikawa, kuma siyar da combo yana cire ajiya daga kayan da suka haɗa shi. Idan an kashe, ana fara haɗa combo cikin ajiya da Daidaitawa.',
'Virtual_Combo_Stock_Warning' => 'Ya fi kyau a zaɓa kafin a fara siyar da combo. Bayan an siyar ko an mayar da combo, sauyawa zai sa gyare-gyare, gogewa da mayarwa na waɗannan takardu daga baya su juya ajiyar kayansu ta hanyar da ba daidai ba.',
'Virtual_Combo_Stock_Confirm_On_Title' => 'A kunna ajiyar combo ta kama-da-wane?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'Za a siyar da combo kai tsaye daga kayan da suka haɗa su, kuma ba za a ƙara amfani da ajiyar kayansu ta kansu ba.',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'A kashe ajiyar combo ta kama-da-wane?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'Combo za su koma kan ajiyar kayansu ta kansu, wadda dole a haɗa ta daga kayan da suka haɗa su da Daidaitawa kafin a iya siyar da su.',
'Home_Warehouse' => 'Sito na asali',
'Home_Warehouse_Hint' => 'Reshen da wannan kaya yake nasa. Masu amfani da aka iyakance ga wasu sitoci ba za su gan shi ba sai an canja ajiyar kaya zuwa gare su.',
'Home_Warehouse_Required' => 'Zaɓi sito da wannan kaya yake nasa.',
'Combo_products_required' => 'Ƙara aƙalla kaya ɗaya a cikin combo.',
'Customer_Performance_Help' => 'Nuna makin ƙwazo da ƙima a shafin abokin ciniki, wanda aka gina daga amincin biya, yadda suka saya kwanan nan da yawan mayarwarsu.',
'Product_Supplier' => 'Mai kaya a kan kayayyaki',
'Product_Supplier_Help' => 'Yana ƙara filin mai kaya na asali a fom ɗin kaya, yana nuna shi a matsayin ginshiƙi a jerin kayayyaki, kuma yana ba ku damar tace kayayyaki bisa mai kaya don gina jerin sake oda.',
