'Account_Ledger' => 'Littafin Asusu',
'Closing_Balance' => 'Saura na Rufewa',
'Recon_Intro' => 'Yana kwatanta saura na aiki na kowane asusun tsabar kuɗi da na banki da saura a Babban Littafi (General Ledger) na asusun littafin da aka haɗa shi da shi. Wannan shafin karantawa ne kawai: ba ya taɓa canza ko ɗaya daga cikin sauran biyu.',
'Recon_Auto_Off' => 'An kashe rubuce-rubucen lissafi na atomatik, don haka ba a rubuta sababbin ma’amaloli a Babban Littafi kuma za su bayyana a matsayin rubutun lissafi da ya ɓace. Kunna su a Saituna → Maɓallan Fasali.',
