'Tg_Guide_Step3_Body' => 'A shafin {settings} liƙa token na bot da chat ID, zaɓi {allEvents} ko waɗanda kuke so kawai ({events}…), kunna {enable} sannan ajiye. Sa’an nan danna {sendTest}.',
'Tg_Guide_State_Enabled' => 'an kunna',
'Tg_Guide_State_Saved_Off' => 'an ajiye, amma an kashe',
'Tg_Guide_State_Not_Configured' => 'ba a saita ba tukuna',
'Tg_Guide_Chat_Id' => 'hira {id}',
'Tg_Guide_How_Sent' => 'Yadda ake aika saƙonni',
'Tg_Guide_A_Title' => 'Nan take — babu abin da za a sanya',
'Tg_Guide_A_Body' => 'Siyarwa, siyan kaya, biya ko kuɗaɗen fita da aka ajiye a Stocky — a POS ko a admin — ana aika su zuwa Telegram {rightAfter} an ajiye su, a cikin buƙata ɗaya. Babu shigarwar cron, babu queue worker, kuma mai karɓar kuɗi ba ya jiran Telegram: an riga an amsa siyarwar kafin saƙon ya fita.',
'Tg_Guide_Right_After' => 'nan da nan bayan',
'Tg_Guide_B_Title' => 'Shigarwar cron — don sake gwadawa da abubuwan da ke faruwa a bango',
'Tg_Guide_B_Body' => 'Nau’ukan saƙo biyu suna jira a layin Telegram na musamman maimakon haka: aikawar da ta kasa (ba a samu Telegram na ɗan lokaci ba), wadda ake sake gwadawa har sau uku a cikin ’yan mintuna masu zuwa; da abubuwan da suka faru a wajen admin — odar da aka shigo da su daga WooCommerce ko Shopify, umarnin artisan. Wannan shigarwar cron ce ke aika su, ba wani abu ba:',
'Tg_Guide_B_Note' => 'Kowane minti ya dace: gudu ba tare da komai a jira ba yana fita nan take. A cPanel wannan yana shiga {cronJobs} — yi amfani da cikakken hanyar PHP 8.2+ idan {php} ya tsufa. A Windows, yi amfani da Task Scheduler da program {php2}, arguments {args}, start in {path}.',
'Tg_Guide_N_Waiting' => '{n} suna jiran a aika',
'Tg_Guide_Nothing_Waiting' => 'babu abin da ke jira',
'Tg_Guide_N_Gave_Up' => '{n} an daina bayan sake gwadawa',
'Tg_Guide_Growing_Hint' => '— idan wannan lamba ta ci gaba da ƙaruwa, shigarwar cron ba ta aiki.',
'Tg_Guide_Without_Cron' => 'Ba tare da shigarwar cron ba, duk abin da aka ajiye a Stocky yana isowa nan take; kawai kuna rasa sake gwadawa da odar da aka shigo da su.',
'Tg_Guide_Else_Title' => 'Sauran duka',
'Tg_Guide_Else_Body' => 'Saƙonnin abubuwan da suka faru a bango dandamalin ne ke isar da su — babu abin da za a saita.',
'Tg_Guide_Not_Arrive' => 'Idan bai iso ba',
'Tg_Guide_Err_401' => '{code} — token na bot ba daidai ba ne. Sake liƙa shi daga BotFather.',
'Tg_Guide_Err_400' => '{code} — chat ID ba daidai ba, ko bot ɗin ba ya cikin ƙungiyar. Don hira ta kai, fara aika saƙo zuwa bot ɗin.',
'Tg_Guide_Err_403' => '{code} — sake ƙara bot ɗin cikin ƙungiyar, ko a matsayin mai gudanarwa na tashar.',
'Tg_Guide_Test_Works' => 'Gwajin yana aiki amma saƙonnin siyarwa ba sa isowa',
'Tg_Guide_Test_Works_Item' => '{label} — duba cewa an zaɓi abin da ya faru (ko an zaɓi {allEvents}) kuma an kunna maɓallin.',
'Tg_Guide_Imported_Never' => 'Odar da aka shigo da su ba sa isowa',
'Tg_Guide_Imported_Never_Item' => '{label} — shigarwar cron da ke sama ba ta aiki.',
'Jumia_Hero_Title' => 'Daidaitawar kasuwar Jumia',
'Jumia_Hero_Desc' => 'Tura farashi da ajiyar kaya zuwa jerin kayanku a Jumia Seller Center kuma shigo da odar kasuwa a matsayin siyarwa.',
'Jumia_Api_Url_Label' => 'API URL (endpoint na Seller Center na ƙasarku)',
'Jumia_Account_Email' => 'Imel ɗin asusu (User ID)',
'Jumia_Prices_Stock' => 'Farashi & Ajiyar Kaya',
'Jumia_Push_Card_Title' => 'Tura farashi & ajiyar kaya zuwa Jumia',
'Jumia_Push_Desc' => 'Yana aika farashin yanzu da adadi na kowane kaya (da nau’i) da ke da SKU da ya yi daidai da {sellerSku} na jerin kayan Jumia. Ana aika sabuntawa a matsayin feeds na Seller Center kuma ana aiwatar da su daga baya ba nan take ba — ana rubuta ID na feed a shafin Rajistoci, kuma ƙin kowane abu yana bayyana a allon matsayin feed na Seller Center.',
'Jumia_Push_Prices_Stock' => 'Tura farashi & ajiyar kaya',
'Jumia_Orders_Desc' => 'Yana shigo da odar kasuwa a matsayin siyarwa (lambobi kamar {ref}), an haɗa su da kayayyakinku ta Seller SKU. Ana tsallake odar da aka riga aka shigo da su da waɗanda aka soke, don haka jawo su akai-akai ba shi da haɗari. Ana yi wa biya alamar an biya ne kawai ga odar da aka isar (Jumia galibi COD ce).',
'Jumia_Guide_1' => 'A Jumia {sellerCenter}, buɗe Settings → {integrationMgmt} kuma ƙirƙiri maɓallin API.',
'Jumia_Guide_2' => 'Shigar da API URL na ƙasarku (misali {ng} don Najeriya, {ke} don Kenya, {eg} don Masar), imel ɗin asusunku na Seller Center, da maɓallin — sannan gudanar da {test}.',
'Jumia_Guide_3' => 'Tabbatar cewa {sellerSku} na kowane jerin kaya na Jumia ya yi daidai da lambar kaya ta Stocky — wannan ce shaidar da ake amfani da ita wajen tura ajiyar kaya da kuma haɗa oda.',
'Jumia_Guide_4' => 'Tura farashi & ajiyar kaya bayan canjin ajiyar kaya; jawo oda akai-akai (Jumia ba ta da webhooks a wannan API).',
'Jumia_Guide_5' => 'Ƙirƙirar sababbin jerin kaya yana nan a Seller Center — Jumia tana buƙatar halaye na musamman ga kowane rukuni da duba hotuna, waɗanda tasharsu kawai ke sarrafawa yadda ya kamata.',
'Mc_Hero_Title' => 'Daidaitawar audience na Mailchimp',
'Mc_Hero_Desc' => 'Riƙe audience na Mailchimp cike da abokan cinikinku, domin ku iya gudanar da kamfen ɗin imel a kan ainihin abokan cinikinku.',
'Mc_Account_Audience' => 'Asusu & audience',
'Mc_Api_Key_Placeholder' => 'misali a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'Audience',
'Mc_N_Members' => '(mambobi {n})',
'Mc_Load_Audiences_To_Pick' => 'Loda audiences don zaɓar ɗaya',
'Mc_Load_Audiences' => 'Loda audiences',
'Mc_Double_Opt_In_Label' => 'Double opt-in — sababbin mambobi suna samun imel na tabbatarwa kafin su shiga',
'Mc_Recommended_GDPR' => '(ana ba da shawara saboda GDPR)',
'Mc_Auto_Sync_New' => 'Daidaita sababbin abokan ciniki ta atomatik yayin da ake ƙirƙirar su',
'Mc_With_Email' => 'Masu imel',
'Mc_Push_Desc' => 'Yana sabuntawa ko ƙara kowane abokin ciniki mai adireshin imel cikin audience da aka zaɓa (har da suna da waya). Mambobin da ke akwai suna riƙe matsayin rajistarsu — ba za a sake yi wa wanda ya cire rajistarsa rajista ba. Ana barin abokan ciniki marasa imel.',
'Mc_Double_Opt_In_Off' => 'Double opt-in a kashe yake',
'Mc_Double_Opt_In_Off_Desc' => 'Za a ƙara sababbin mambobi a matsayin masu rajista ba tare da imel na tabbatarwa ba. Ku yi haka ne kawai ga abokan cinikin da suka riga suka yarda su karɓi saƙonnin tallatawa.',
'Mc_Guide_1' => 'A Mailchimp, buɗe {path} kuma ƙirƙiri maɓalli (yana ƙarewa da {suffix} — wannan ƙarshen shi ne datacenter ɗinku).',
'Mc_Guide_2' => 'Liƙa maɓallin a nan, ajiye, sannan danna {load} ka zaɓi audience da za a cika.',
'Mc_Guide_3' => 'Bar {doi} a kunne sai dai idan abokan cinikinku sun riga sun yarda da imel ɗin tallatawa.',
'Mc_Double_Opt_In_Lower' => 'double opt-in',
'Mc_Guide_4' => 'Gudanar da {push} don cikawa na farko; kunna {autoSync} domin sababbin abokan ciniki su shiga ta atomatik.',
'Mc_Auto_Sync_Lower' => 'daidaitawa ta atomatik',
'Mc_Consent_Matters' => 'Izini yana da muhimmanci',
'Mc_Consent_Desc' => 'Aika imel ga mutanen da ba su taɓa yarda da tallatawa ba na iya karya dokar GDPR/CAN-SPAM kuma a dakatar da asusun Mailchimp ɗinku. Double opt-in yana mayar da tabbatarwa hannun Mailchimp — zaɓi mafi aminci.',
'Mc_No_Audiences' => 'Ba a sami audiences a wannan asusun ba.',
'Presta_Hero_Desc' => 'Daidaita kayayyaki, ajiyar kaya da oda da shagon PrestaShop ɗinku ta API ɗin webservice ɗinsa.',
'Presta_Webservice_Key' => 'Maɓallin webservice',
'Presta_Key_Placeholder' => 'Daga Advanced Parameters → Webservice',
'Presta_Key_Help' => 'Kunna webservice a PrestaShop (Advanced Parameters → Webservice), ƙirƙiri maɓalli mai izini a kan products, stock_availables, orders da customers, kuma liƙa shi a nan. Ana adana shi ta yadda ba za a iya karanta shi ba.',
'Presta_Shop_Language_ID' => 'ID na harshen shago',
'Presta_Language_Help' => 'ID na harshe da ake amfani da shi don sunayen kayayyaki lokacin turawa (1 = harshen farko na shagon).',
'Presta_Push_Desc' => 'Yana ƙirƙirar kayayyaki masu sauƙi da ba su nan a PrestaShop (tare da ajiyar kayansu ta yanzu). Ana tsallake kayayyakin da aka riga aka haɗa da kayayyaki masu nau’i — ci gaba da gyara bayanan kaya a PrestaShop, ko jawo don sabunta kwafin da ke nan.',
'Presta_Pull_Desc' => 'Yana shigo da kayayyakin PrestaShop, yana haɗa waɗanda ke akwai ta reference (SKU) kuma yana ƙirƙirar sauran. Ana shigo da combinations a matsayin kayan iyayensu.',
'Presta_Reset_Confirm' => 'A sake saita haɗin kayayyaki? Tarihin oda yana riƙe haɗinsa.',
'Presta_Stock_Desc' => 'Yana sabunta ajiyar kayan shagon (stock_availables) ga kowane kaya da aka haɗa.',
'Presta_Orders_Desc' => 'Yana shigo da odar shago a matsayin siyarwa (lambobi kamar {ref}), sababbi farko. Ana tsallake odar da aka riga aka shigo da su da waɗanda aka soke, don haka jawo su akai-akai ba shi da haɗari. PrestaShop ba shi da webhooks — gudanar da wannan bayan lokutan cunkoso.',
'Presta_Guide_1' => 'A back office na PrestaShop ɗinku, buɗe {path} kuma kunna webservice.',
'Presta_Guide_2' => 'Ƙara sabon maɓalli, ka ba da {vae} a kan {products} da {stock}, da {view} a kan {orders} da {customers}.',
'Presta_Guide_3' => 'Liƙa URL na shago da maɓallin a shafin Haɗi, ajiye, sannan gudanar da {test}.',
'Presta_Guide_4' => 'Fara jawo kayayyaki idan shagon yana da kundin kaya (yana haɗawa ta reference/SKU); tura don ƙirƙirar kayayyaki masu sauƙi da ba su nan.',
'Presta_Guide_5' => 'Tura ajiyar kaya duk lokacin da adadi ya canza, kuma jawo oda akai-akai — PrestaShop ba shi da webhooks, don haka oda tana isowa ne kawai idan kun jawo.',
'Presta_Identity_Title' => 'Shaidar kaya ita ce reference (SKU)',
'Presta_Identity_Desc' => 'Ana haɗa lambar kaya ta Stocky da reference na PrestaShop. Riƙe reference daidai a ɓangarorin biyu; ana haɗa combinations (nau’uka) a cikin oda ta reference amma ba a tura su a wannan sigar.',
'Gs_Hero_Title' => 'Fitarwar Google Sheets',
