'Gs_Redirect_Uri_Title' => 'Redirect URI na Google OAuth client',
'Gs_Export_Desc' => 'Kowace fitarwa tana sake rubuta shafinta daga farko (kanun + duk layuka), don haka takardar kullum cikakken hoto ne na halin yanzu. Ana aika manyan bayanai rukuni-rukuni — bar shafin a buɗe har sai ƙidaya ta tsaya.',
