'Gs_Snapshots_Desc' => 'Fitarwa tana sake rubuta shafukan Sales / Products / Customers idan an buƙata. Don sabuntawa kai tsaye layi-layi a kowace siyarwa, haɗa Zapier — yana iya ƙara layuka a lokacin da abubuwa suka faru.',
