'Xero_Redirect_Uri_Title' => 'Redirect URI na app ɗin Xero',
'Xero_Redirect_Help' => 'Ƙirƙiri "Web app" a kan {link} kuma ka yi rajistar wannan redirect URI. Lura: alamun shiga (access tokens) na Xero suna sabunta kansu, amma haɗin da ya yi kwanaki sama da 60 ba a yi amfani da shi ba dole a sake haɗa shi.',
'Xero_Contacts_In_Xero' => 'Contacts a cikin Xero',
'Xero_Invoices_In_Xero' => 'Rasitoci a cikin Xero',
'Xero_Payments_Recorded' => 'Biyan da aka rubuta',
'Xero_Push_Customers_Desc' => 'Yana ƙirƙira ko sabunta contact na Xero ga kowane abokin ciniki. Abokin ciniki wanda sunansa ya riga ya kasance a Xero za a haɗa shi da wannan contact ɗin.',
'Xero_Push_Sales_As_Invoices' => 'Tura siyarwa a matsayin rasitoci',
'Xero_Push_Invoices_Desc' => 'Yana ƙirƙirar rasiti ɗaya mai matsayin AUTHORISED ga kowace siyarwa (lambar rasiti = Ref na siyarwa), tare da layukan kayan siyarwar da kuma layukan isarwa, ragi da haraji domin jimillar Xero ta yi daidai da jimillar siyarwa. Ana tsallake siyarwar da ke cikin Xero tuni — ba a taɓa gyara rasitoci. Ana ƙirƙirar contacts da suka ɓace nan take.',
