'Xero_Guide_4' => 'Danna {connect}, shiga kuma ka zaɓi ƙungiyar da za a haɗa.',
'Xero_Guide_5' => 'Duba lambobin asusu: asusun siyarwa yana karɓar layukan rasiti; saita lambar asusun banki idan siyarwar da aka biya ya kamata ta kuma rubuta biya.',
'Xero_Guide_6' => 'Tura abokan ciniki da farko, sannan rasitoci. Lambobin rasiti su ne Ref na siyarwa, don haka Xero zai ƙi kwafi ko da an sake saita haɗi.',
'Xero_Tax_Inclusive_Title' => 'Ana tura adadi tare da haraji a ciki kamar yadda suke',
'Xero_Tax_Inclusive_Desc' => 'Rasitoci suna amfani da layukan NoTax waɗanda suke kwaikwayon siyarwar daidai (kaya + isarwa − ragi + haraji), don haka jimillar Xero koyaushe tana daidai da jimillar Stocky. Akawuntanka zai iya sake tura layukan haraji da isarwa zuwa asusun da suka dace a cikin Xero.',
