'Salla_Only_Unlinked' => 'Kayayyakin da ba a haɗa ba tukuna kawai',
'Salla_Pull_Desc' => 'Yana shigo da kayayyakin Salla (har da nau’ikansu), yana daidaita waɗanda ke akwai ta SKU kuma yana ƙirƙirar sauran.',
'Salla_Reset_Confirm' => 'Sake saita haɗin kaya da nau’i? Tarihin oda zai riƙe haɗinsa.',
'Salla_Stock_Desc' => 'Yana aika adadin da ke akwai yanzu na kowane kaya da aka haɗa (ta SKU) da kowane nau’i da aka haɗa.',
'Salla_Orders_Desc' => 'Sabbin oda na Salla galibi suna zuwa da kansu ta webhooks kuma su zama siyarwa. Yi amfani da wannan jawowar don cike oda da aka yi kafin a saita webhook — ana tsallake oda da aka riga aka shigo da su.',
