'Fbr_Page_Title' => 'Rasiti na Dijital na FBR (Pakistan)',
'Fbr_Token_Saved' => 'An ajiye token (••••{last4}). Bar shi babu komai don riƙe shi.',
'Fbr_Token_Obtain' => 'Samu token daga tashar e-invoicing ta PRAL / IRIS.',
'Fbr_Token_Placeholder' => 'Liƙa token daga tashar e-invoicing ta PRAL / IRIS',
'Fbr_Guide_What_Title' => 'Menene FBR Digital Invoicing?',
'Fbr_Guide_What_Body' => 'A ƙarƙashin SRO 69(I)/2025, Federal Board of Revenue (Pakistan) tana buƙatar kasuwancin da aka haɗa su riƙa ba da rahoton rasitocin siyarwa ta na’ura kai tsaye ta hanyar API na PRAL Digital Invoicing (DI). Kowace siyarwa da aka karɓa tana samun lambar rasitin FBR ta hukuma, kuma dole rasitoci su nuna wannan lamba tare da lambar QR ta tabbatarwa.',
'Fbr_Guide_Steps_Title' => 'Matakan fara aiki na gaske',
'Fbr_Guide_Step_1' => 'Yi rajista a tashar e-invoicing ta FBR IRIS kuma ka samu security token na {sandbox}.',
'Fbr_Guide_Step_2' => 'Saita bayanan mai sayarwa a shafin Saiti (NTN/CNIC, sunan kasuwanci, lardi, adireshi), liƙa token, kuma ka kunna haɗin tare da muhalli a kan {sandbox}.',
'Fbr_Guide_Step_3' => 'Yi siyarwar gwaji da ta shafi yanayi(n) da FBR ta ba ka (zaɓi yanayin a filin Yanayin Sandbox). Duba shafin Takardu don tabbatar da cewa sun dawo {valid}.',
'Fbr_Guide_Step_4' => 'Da zarar FBR ta amince da gwajin sandbox ɗinka, samu token na {production} daga tashar, liƙa shi a nan, kuma ka sauya muhallin zuwa {production}.',
'Fbr_Guide_Step_5' => 'Rasitoci suna nuna lambar rasitin FBR da lambar QR kai tsaye da zarar an karɓi siyarwa — babu ƙarin matakai da ake buƙata a wurin siyarwa.',
'Fbr_Sandbox_Lower' => 'sandbox',
'Fbr_Production_Lower' => 'production',
'Fbr_Guide_Note_1' => 'Saita HS codes na kowane kaya a fom ɗin kaya (filin "HS Code"). HS Code na Asali da aka saita a nan ana amfani da shi ne kawai ga kayayyakin da ba su da shi.',
'Fbr_Guide_Note_2' => 'Ana ba da rahoton abokan ciniki masu shigowa da ba su yi rajista ba ga FBR a matsayin "Unregistered".',
'Fbr_Guide_Note_3' => 'Masu saye da suka yi rajista suna buƙatar a shigar da NTN ɗinsu a filin Lambar Haraji na abokin ciniki don a ba da rahotonsu a matsayin masu rajista.',
'Fbr_Guide_Note_4' => 'Ana iya sake gwada aikawar da ta gaza ko mara inganci daga shafin Takardu bayan an gyara dalilin; shafin Bayanai (Logs) yana nuna musayar API ta asali don gano matsala.',
