'Woo_WordPress_Username' => 'Sunan mai amfani na WordPress',
'Woo_WordPress_App_Password' => 'Kalmar sirri ta manhaja (Application Password) ta WordPress',
'Woo_Automatic_Sync' => 'Daidaitawa ta atomatik',
'Woo_Auto_Sync_Intro' => 'Tura canje-canjen da aka yi a Stocky zuwa WooCommerce nan take, ba tare da buɗe wannan shafi ba. Kowace turawa tana gudana ne nan da nan bayan an ajiye aikin, don haka mai karɓar kuɗi ba ya jiran WooCommerce. Sakamako yana bayyana a shafin Rajista.',
'Woo_Auto_Sync_Products_Help' => 'Kayan da aka ƙirƙira, aka gyara ko aka kwafa a Stocky ana tura shi zuwa WooCommerce (bayanai, farashi, nau’o’i, hotuna, ajiyar kaya). Ba a tura shigo da kaya da yawa a lokaci ɗaya; bayan shigo da su, yi amfani da Daidaita — POS → WooCommerce a shafin Kayayyaki.',
'Woo_Auto_Sync_Stock_Help' => 'Duk wani motsin ajiyar kaya (siyarwar POS, siyarwa, mayarwa, siyan kaya, daidaitawa, canja wuri) yana sabunta yawan kayayyakin da abin ya shafa a WooCommerce. Kayayyakin da aka riga aka haɗa da WooCommerce kaɗai ake sabuntawa.',
'Woo_Sync_Tuning' => 'Tsara daidaitawa',
'Woo_Sync_Tuning_Intro' => 'Tsoffin saitunan sun dace da yawancin shaguna. Canza waɗannan kawai idan daidaitawa tana jinkiri ko tana ƙarewa da lokaci a sabar ku. Kowace ƙima an iyakance ta zuwa iyaka mai aminci, kuma share fili yana mayar da tsohon saitinsa.',
'Woo_Sync_Guide' => 'Jagorar Daidaitawa da WooCommerce',
'Woo_Guide_Getting_Keys' => 'Samun maɓallan API',
'Woo_Guide_Keys_1' => 'A cikin WooCommerce: WooCommerce → Settings → Advanced → REST API.',
'Woo_Guide_Keys_2' => 'Danna Add key, zaɓi Read/Write, sannan ku kwafi Consumer key da Consumer secret.',
'Woo_Guide_Keys_3' => 'URL na shago: URL na shafinku ba tare da slash a ƙarshe ba (misali {example}).',
'Woo_Guide_WP_Title' => 'Sunan mai amfani na WP da Application Password (na zaɓi)',
'Woo_Guide_WP_Intro' => 'Ana amfani da waɗannan filaye ne kawai don hotunan kayayyaki. API na WooCommerce (URL na shago + Consumer key/secret) yana daidaita kayayyaki, ajiyar kaya, rukunoni, tambura, abokan ciniki da oda; REST API na WordPress kuma yana kula da Media Library (nema da loda hotuna).',
'Woo_Guide_WP_1' => 'Lokacin daidaita kayayyaki ko ajiyar kaya, Stocky na iya haɗa hotunan kaya: da farko yana neman hoton da ke akwai a Media Library na WordPress ta sunan fayil; idan ba a samu ba, yana loda hoton ta API na WordPress.',
'Woo_Guide_WP_2' => 'Yi amfani da mai amfani na WordPress wanda zai iya sarrafa media (misali Administrator). Ƙirƙiri Application Password a WordPress: Users → Profile (ko mai amfani naku) → Application Passwords — ƙara sabo kuma ku liƙa shi a nan.',
'Woo_Guide_WP_3' => 'Idan kun bar waɗannan babu komai, daidaitawa tana aiki har yanzu ga duk bayanai (kayayyaki, ajiyar kaya, rukunoni, tambura, abokan ciniki, oda); haɗa hotunan kaya (nema/loda) ne kaɗai ake tsallakewa.',
'Woo_Guide_How_To_Enable' => 'Yadda ake kunnawa',
'Woo_Guide_Enable_1' => 'Shigar da URL na shago, Consumer key, da Consumer secret a sama, sannan danna Ajiye.',
'Woo_Guide_Enable_2' => 'Yi amfani da Gwada Haɗin don tabbatar da bayanan shiga.',
'Woo_Guide_Enable_3' => 'Yi amfani da daidaitawa da hannu daga kowane shafi lokacin da kuke buƙatar daidaitawa.',
'Woo_Guide_Enable_4' => 'Kunna Daidaitawa ta atomatik a sama don tura sababbin kayayyaki da waɗanda aka gyara, da kowane canjin ajiyar kaya zuwa WooCommerce nan take.',
'Woo_Guide_Manual_Sync' => 'Daidaitawa da hannu (lokacin da ake buƙata)',
'Woo_Guide_Manual_1' => 'Daidaitawa tana aiki ta hanyoyi biyu: Stocky → WooCommerce da WooCommerce → Stocky.',
'Woo_Guide_Manual_2' => 'Daidaitawa da hannu tana nan a duk shafukan WooCommerce (Kayayyaki, Ajiyar kaya, da sauransu); yi amfani da maɓallan daidaitawa a kowane shafi don yin daidaitawa lokacin da ake buƙata.',
'Woo_Guide_Auto_1' => 'Kayayyaki: idan an kunna, kayan da kuka ƙirƙira, kuka gyara ko kuka kwafa a Stocky ana tura shi zuwa WooCommerce nan da nan bayan kun ajiye shi, sannan ajiyar kayansa ta biyo baya.',
'Woo_Guide_Auto_2' => 'Ajiyar kaya: idan an kunna, kowane canjin ajiyar kaya (siyarwar POS, siyarwa, mayarwa, siyan kaya, daidaitawa, canja wuri) yana sabunta yawa a WooCommerce. Kayayyakin da aka riga aka haɗa da WooCommerce kaɗai ake sabuntawa.',
'Woo_Guide_Auto_3' => 'Daidaitawa ta atomatik tana tura canje-canje daga Stocky zuwa WooCommerce kaɗai. Kawo bayanai daga WooCommerce zuwa Stocky (oda, abokan ciniki, kayayyaki) ana yin sa ne koyaushe da maɓallan da ke shafukan Oda, Abokan Ciniki da Kayayyaki.',
'Woo_Guide_Auto_4' => 'Ba a tura shigo da kayayyaki da yawa a lokaci ɗaya ta atomatik. Bayan shigo da su, yi amfani da Daidaita — POS → WooCommerce a shafin Kayayyaki.',
'Woo_Guide_Auto_5' => 'Ana rubuta kowace turawa ta atomatik a shafin Rajista, don ku iya duba abin da aka tura kuma ku gano kurakurai.',
'Woo_Guide_First_Setup' => 'Saitin farko',
'Woo_Guide_First_1' => 'Gudanar da waɗannan sau ɗaya, bisa wannan tsari, don a haɗa kundin kayanku na yanzu: Daidaita — POS → WooCommerce a shafin Rukunoni, sannan shafin Tambari, sannan shafin Kayayyaki, a ƙarshe kuma Daidaita Ajiyar Kaya a shafin Ajiyar kaya. Bayan haka, kunna Daidaitawa ta atomatik a sama don WooCommerce ya kasance a kan zamani.',
'Woo_Guide_First_2' => 'Manyan daidaitawar kayayyaki da ajiyar kaya suna gudana a ƙananan rukunoni kuma suna nuna ci gabansu a shafin. Ku bar shafin a buɗe har sai daidaitawa ta ƙare; kuna iya dakatar da ita a kowane lokaci.',
'Woo_Guide_First_3' => 'Idan daidaitawa ta daina motsi na ’yan mintoci, duba shafin Rajista, sannan ku tuntuɓi tallafi.',
'Woo_Guide_Notes_1' => 'Canza URL na shago ko maɓallan API yana sake saita haɗe-haɗe (kayayyaki, rukunoni, tambura, abokan ciniki); abubuwa za su sake daidaituwa zuwa shagon (sabon).',
'Woo_Guide_Notes_2' => 'Ku kiyaye SKU iri ɗaya tsakanin Stocky da WooCommerce don guje wa maimaita kayayyaki da kuma sake haɗawa cikin aminci.',
'Store_Banner_Pos_Top_Left' => 'Sama — Hagu',
