'Shp_G_Both_Need' => 'Hanyoyin biyu suna buƙatar wannan da farko',
'Shp_G_Credentials' => 'Bayanan shiga na Shopify',
'Shp_G_Cred_Intro' => 'Tun daga Janairu 2026 Shopify ba ya ƙirƙirar custom apps a cikin admin, don haka akwai nau’ikan haɗi biyu:',
'Shp_G_Cred_Dev' => '{app} (kowane shagon da aka haɗa yanzu) — {path}. Ba da Admin API scopes na abin da wannan shago ke daidaitawa, saka manhajar a shagon, sannan ku kwafi {clientId} da {clientSecret} daga shafin Settings na manhajar zuwa {edit}. ERP yana musanya su da access token da kansa kuma yana sabunta shi kafin ya ƙare kowane awa 24. Client secret ɗin shi ma yana sa hannu a webhooks, don haka babu wani abu da ake buƙata. Dole ne manhajar da shagon su kasance a ƙungiyar Shopify ɗaya.',
'Shp_G_Dev_App' => 'Manhajar Dev Dashboard',
'Shp_G_Cred_Legacy' => '{app} (wanda aka ƙirƙira a admin kafin 2026) — yana ci gaba da aiki ba tare da canji ba da {token} ({prefix}) ɗinsa da {secret} ɗinsa a matsayin sirrin sa hannu na webhook. Ba ƙima ɗaya ba ce da token ɗin, kuma juya su ba daidai ba shi ne dalilin da aka saba ƙin webhooks.',
'Shp_G_Legacy_App' => 'Tsohuwar custom app',
'Shp_G_Api_Secret_Key' => 'API secret key',
'Shp_G_Stored' => 'an ajiye',
'Shp_G_Missing_Refused' => 'ba ya nan — za a ƙi isarwa',
'Shp_G_Targets' => '{path} Sito na ERP wanda wannan shago ke sayar da ajiyar kayansa, da wurin Shopify inda ake rubuta wannan ajiyar kaya. Daidaita ajiyar kaya da shigo da oda duka suna ƙin gudana idan babu su.',
'Shp_G_Currently' => 'Yanzu: sito {warehouse}, wuri {location}',
'Shp_G_Not_Set_Lc' => 'ba a saita ba',
'Shp_G_Ready' => 'a shirye',
'Shp_G_Incomplete' => 'bai cika ba',
'Shp_G_Manual_Syncs' => 'Daidaitawar da kuke farawa da hannu',
'Shp_G_Manual_Body' => 'Daidaitawar da aka fara daga {centre} tana amsawa nan take kuma tana gudana a bayan fage, a ƙananan gutsure waɗanda kowanne ke ci gaba daga inda na baya ya tsaya. Babban kundin kaya ba ya taɓa yankewa a tsakiya saboda buƙatar yanar gizo da lokacinta ya ƙare, kuma rufe shafin ba ya dakatar da ita.',
'Shp_G_Worker_Managed' => 'Dandalinku yana gudanar da worker don haka, don haka babu abin da za a saka.',
'Shp_G_Worker_Cron' => 'Worker ɗin don haka ƙarin layin cron ɗaya ne:',
'Shp_G_Cron_Copied' => 'An kwafi layin cron',
'Shp_G_Worker_Busy' => 'Idan worker yana aiki da wani abu, shafin Sync Centre da ke buɗe yana ci gaba da gudanarwar da kansa bayan ’yan daƙiƙoƙi, buƙata guda ɗaya gajera a lokaci ɗaya — don haka daidaitawa koyaushe tana ƙarewa yayin da kuke kallo.',
'Shp_G_Pick_How' => 'Sannan ku zaɓi yadda zai kasance daidai',
'Shp_G_Right_Away' => 'Nan take',
'Shp_G_Stock_Live' => 'ajiyar kaya kai tsaye',
'Shp_G_Stock_Not_Live' => 'ajiyar kaya ba kai tsaye ba',
'Shp_G_Realtime_Lead' => 'Ana tura kowane canji yayin da yake faruwa, cikin daƙiƙoƙi. Rabi biyu ne, kuma maɓallai ne daban-daban: {webhooks} suna kawo abubuwan da suka faru a shagon cikin tsarin, {push} kuma yana tura ajiyar kaya waje.',
'Shp_G_Webhooks_Lc' => 'webhooks',
'Shp_G_Instant_Push_Lc' => 'turawar ajiyar kaya nan take',
'Shp_G_Webhooks_Heading' => 'Webhooks — shago → ERP',
'Shp_G_Webhooks_Body' => 'Oda, canje-canjen matsayin oda, da gyaran kaya, abokin ciniki da ajiyar kaya da aka yi a Shopify. Buɗe shagon kuma ku danna {button} a {tab} ɗinsa — babu matsala idan an danna sau biyu. Shopify yana tura wa:',
'Shp_G_Webhooks_Tab' => 'shafin Webhooks',
'Shp_G_Webhooks_Note' => 'Dole ne a iya isa ga adireshin daga intanet ta HTTPS — Shopify ba zai isar zuwa {localhost} ko domain na {test} ba. Ana rubuta kowace isarwa sau ɗaya, don haka sake gwadawar Shopify ba za ta iya ƙirƙirar oda mai maimaitawa ba, kuma ana iya sake gudanar da wadda ta gaza. Ana ƙin isarwa har sai an ajiye sirrin sa hannu daga mataki na 1.',
'Shp_G_Push_Heading' => 'Turawar ajiyar kaya nan take — ERP → shago',
'Shp_G_People_Miss' => 'Wannan shi ne saitin da mutane ke mantawa',
'Shp_G_Push_P1' => 'Siyarwar POS {not} za ta isa Shopify da kanta ba. Idan aka bar shi a kashe, shagon zai gano ne kawai a matakin turawar Inventory na gaba — kuma a cikin wannan tazara zai iya sayar da kayan da kuka riga kuka sayar a kanti.',
'Shp_G_Not' => 'ba',
'Shp_G_Push_P2' => 'Duba {setting} a {path}. Wannan shi ne duk saitin — babu worker, babu cron. Daga nan kowace siyarwa, mayarwa da daidaitawa tana tura waɗannan kayayyakin kaɗai, nan da nan bayan an ajiye siyarwar, kuma siyarwa mai layi ashirin turawa ɗaya ce kawai, ba ashirin ba. Kanti ba ya taɓa jiran ta.',
'Shp_G_This_Store' => 'Wannan shago:',
'Shp_G_Push_On' => 'a kunne — ana tura ajiyar kaya idan ta canza',
'Shp_G_Push_Off' => 'a kashe — ajiyar kaya bisa jadawali kawai',
'Shp_G_Push_Note' => 'Kayayyakin da suka riga suna da haɗin Shopify kaɗai, da motsin da ke cikin sito na wannan shago kaɗai, ake turawa. Ayyuka masu yawa — goge kaya, sake saita sito — suna rubuta ajiyar kaya ba tare da harba wani abu ba, wanda yana ɗaya daga cikin dalilan da za a ci gaba da matakin ajiyar kaya da aka tsara.',
'Shp_G_Nothing_Else' => 'Babu wani abu da za a saka',
'Shp_G_Nothing_Else_Body' => 'Babu rabin da ke buƙatar queue worker ko layin cron. Webhook da ke shigowa ana sarrafa shi a cikin buƙatar da Shopify ya yi; turawar ajiyar kaya da ke fita tana gudana a cikin aikin da ya yi wa siyarwar hidima, {after} an mayar da amsa — don haka kanti ba ya taɓa jiran Shopify, kuma shagon da ya daina amsawa ana barin sa bayan daƙiƙa goma a bar shi ga turawar ajiyar kaya da aka tsara ta gaba.',
'Shp_G_After' => 'bayan',
'Shp_G_Exception' => 'Banda guda ɗaya: canjin ajiyar kaya da aikin bayan fage ya yi ba shi da amsar da zai biyo bayanta, don haka ana saka shi a layin {queue} maimakon haka.',
'Shp_G_Queue_Managed' => 'Dandalinku ya riga yana gudanar da worker a wannan layi, don haka waɗannan ma suna fita da kansu.',
'Shp_G_Queue_Cron' => 'Idan kuna son waɗannan ma su fita da wuri, ku gudanar da wannan layi:',
'Shp_G_On_Schedule' => 'Bisa jadawali',
'Shp_G_On_Lc' => 'a kunne',
'Shp_G_Off_Lc' => 'a kashe',
'Shp_G_Scheduled_Lead' => 'Ana sake duba komai lokaci zuwa lokaci, ta hanyoyi biyu. Ya fi lokaci-kai-tsaye jinkiri, amma shi ne ke tura ajiyar kaya a shagunan da ba sa amfani da turawa nan take, shi ke kama webhook da aka rasa, kuma shi ne hanya ɗaya tilo ta matsar da dukkan kundin kaya.',
'Shp_G_Nothing_To_Install' => 'Babu abin da za a saka',
'Shp_G_Managed_Body' => 'Ana gudanar muku da mai tsara lokaci: kowane minti biyar dandalinku yana tambayar kowane shago ko lokacin wani mataki na tsarinsa ya yi, kuma yana gudanar da waɗanda lokacinsu ya yi. Babu layin cron da za a ƙara kuma babu sabar da za a kula da ita.',
'Shp_G_Managed_Note' => 'Minti biyar kuma shi ne mafi ƙanƙantar tazarar da tsari zai iya amfani da ita, saboda minti biyar ita ce mafi gajeriyar tazarar mataki. Ana bin dogayen tazara daidai — matakin da aka saita zuwa minti 30 ana duba shi sau shida kuma yana gudana sau ɗaya.',
'Shp_G_Cron_Entry' => 'Layin cron',
'Shp_G_Cron_Body' => 'Babu abin da aka tsara da ke gudana ba tare da shi ba. Layi ɗaya, don wannan module kaɗai — ƙara shi kusa da duk wani abin da kuka zaɓa ku tsara:',
'Shp_G_Cron_Note' => 'Kowane minti biyar shi ne mafi ƙanƙantar tazarar da tsari zai iya amfani da ita, saboda minti biyar ita ce mafi gajeriyar tazarar mataki. Layin da ya fi tsawo kawai ya zama mafi ƙarancin tazara — da {every15}, matakin da aka saita zuwa minti 5 yana gudana kowane minti 15. A Windows yi amfani da Task Scheduler: program {php}, arguments {args}, started in {path}.',
'Shp_G_Switch_On' => 'Kunna shi, kuma ku zaɓi tsari',
'Shp_G_Plan_Body' => '{path} Maɓallin yana ƙayyade ko mai tsara lokaci zai iya yin aiki ko kaɗan; tsarin kuma yana ƙayyade abin da zai yi. {step} nau’in bayanai ɗaya ne a hanya ɗaya da tazararsa — {ex1}, {ex2}. Ana amfani da tazara ta asali ga kowane mataki da ya bar akwatinsa babu komai.',
'Shp_G_Step_Lc' => 'mataki',
'Shp_G_Ex1' => 'Oda · Shopify → ERP kowane minti 15',
'Shp_G_Ex2' => 'Ajiyar kaya · ERP → Shopify kowane minti 30',
'Shp_G_Plan_Note' => 'Idan kun bar tsarin babu komai, shagon yana jawo oda kuma yana tura ajiyar kaya a tazara ta asali, wanda shi ne abin da yawancin shaguna ke so. Oda jawowa kawai ake yi: a Shopify ne abokin ciniki ke yin oda.',
'Shp_G_Schedule_On' => 'jadawali a kunne',
'Shp_G_Schedule_Off' => 'jadawali a kashe — da hannu kawai',
'Shp_G_When_Runs' => 'Yaushe mataki ke gudana a zahiri',
'Shp_G_When_Body' => 'Lokacin mataki yana yi idan an {started} wannan mataki na ƙarshe fiye da tazararsa, bisa tarihin gudanarwa. Don haka daidaitawar da kuka fara da hannu tana jinkirta ta atomatik ta gaba, kuma matakin da ke ci gaba da gazawa ana sake gwada shi bisa tazararsa maimakon a kowane bugun lokaci. Taƙaitaccen bayanin shagon yana nuna gudanarwar ƙarshe ta kowane mataki, lokacin na gaba, da dalilin da ya hana shi idan an hana shi. Gudanar da turawar kundin kaya ta farko da hannu daga Sync Centre — a matsayin gwaji ba tare da rubutawa ba da farko — kafin a saka shi a jadawali.',
'Shp_G_Started_Lc' => 'fara',
'Shp_G_Where_Setting' => 'Inda kowane saiti yake',
'Shp_G_Where_Note' => 'Duk waɗannan suna kan shagon da ke akwai: {path}, sannan fensir (ko {edit} a shafin shagon kansa).',
'Shp_G_Product_Images' => 'Hotunan kaya',
'Shp_G_Img1' => 'Hotuna suna fita tare da kaya a lokacin {push} — babban hoto da farko, sannan gidan hotuna, sannan ɗaya ga kowane nau’i da ke da nasa, har zuwa hamsin.',
'Shp_G_Products_Push' => 'turawar kayayyaki',
'Shp_G_Img2' => 'Ana loda hoton nau’i tare da kayan sannan a {assigned}, wanda shi ne yadda Shopify ke tsara shi: nau’i yana nuni zuwa ɗaya daga cikin hotunan kayan. Nau’in da ke sake amfani da babban hoto ba ya loda shi sau biyu.',
'Shp_G_Assigned' => 'sanya shi ga wannan nau’in',
'Shp_G_Img3' => 'Hoton da aka ajiye a matsayin fayil ana {uploaded} shi zuwa Shopify, ba a haɗa shi da mahaɗi ba, don haka yana aiki ko da ba za a iya isa ga wannan shigarwar daga intanet ba. Hoton da aka ƙara a matsayin mahaɗin da aka liƙa ana miƙa wa Shopify a matsayin wannan URL, wanda dole ne a iya isa gare shi a bainar jama’a.',
'Shp_G_Uploaded' => 'loda',
'Shp_G_Img4' => 'Ana sake tura su ne kawai idan sun canza a zahiri — turawar da ke canza farashi kawai tana barin hotunan shagon yadda suke, saboda tura su yana maye gurbin dukkan saitin.',
'Shp_G_Img5' => 'Goge hoto a ERP {not} zai goge shi a Shopify ba. Ku goge shi a can ma, ko kuma shagon zai ci gaba da nuna shi.',
'Shp_G_Commands' => 'Umarnin da ya kamata a sani',
'Shp_G_Command_Copied' => 'An kwafi umarni',
'Shp_G_Foot' => 'Kowace daidaitawa tana rubutawa zuwa {logs}, kuma Taƙaitaccen bayanin kowane shago yana nuna lokacin da kowane mataki ya gudana na ƙarshe, lokacin na gaba, da abin da ke hana shi idan akwai. A nan ne za ku fara duba idan daidaitawa ba ta yi abin da kuke tsammani ba.',
'Shp_G_Covers' => 'Ya ƙunshi',
'Shp_G_Speed' => 'Sauri',
'Shp_G_Needs' => 'Yana buƙata',
'Shp_G_Switched_On_At' => 'Inda ake kunna shi',
'Shp_G_Way_Covers_Rt' => 'Oda da gyare-gyaren da aka yi a Shopify; ajiyar kaya da ke barin ERP (siyarwar POS, mayarwa, daidaitawa)',
'Shp_G_Way_Covers_Sc' => 'Komai, ta hanyoyi biyu — har da turawar kundin kaya da duk abin da hanya mai sauri ta rasa',
'Shp_G_Seconds' => 'Daƙiƙoƙi',
'Shp_G_Way_Speed_Sc' => 'Tazarar matakin (minti 5 zuwa kwana 7)',
'Shp_G_Way_Needs_Rt' => 'Adireshin HTTPS na jama’a da sirrin sa hannu don webhooks masu shigowa. Ajiyar kaya mai fita ba ta buƙatar komai',
'Shp_G_Way_Needs_Sc' => 'Mai tsara lokaci, kowane minti biyar',
'Shp_G_Way_Switch_Sc' => '{path}, da tsarin',
'Shp_G_Scope_Orders' => '{a} ({b} don odar da ta wuce kwana 60)',
'Shp_G_Admin_Scopes' => 'Izinin Admin API (scopes)',
'Shp_G_Setting' => 'Saiti',
