'Shp_G_What1' => 'Bayanan shiga daga manhajar Shopify (Dev Dashboard ko tsohuwar custom app).',
'Shp_G_Set2' => 'Sito na ERP, wurin Shopify',
'Shp_G_What2' => 'Wace ajiyar kaya wannan shago ke sayarwa, da inda ake ajiye oda.',
'Shp_G_What3' => 'Farashin dillanci, na jumla ko mafi ƙanƙanta.',
