'Shp_G_What4' => 'Ko jawowa za ta iya ƙirƙirar bayanan ERP da ba ta iya daidaitawa ba.',
'Shp_G_Set5' => 'Waɗanne nau’o’in bayanai ake daidaitawa ko kaɗan',
'Shp_G_What5' => 'A kashe a nan yana nufin a kashe ko’ina — da hannu, bisa jadawali da webhook.',
'Shp_G_What6' => 'Maɓallin mai tsara lokaci.',
'Shp_G_What7' => 'Turawar ajiyar kaya nan take, ana saka ta a layi idan an yi siyarwa ko daidaitawa.',
'Shp_G_Set8' => 'Tazara ta asali, da tsarin matakai',
'Shp_G_What8' => 'Abin da ke gudana da kansa, ta wace hanya, da sau nawa.',
'Shp_G_Cmd1' => 'Kowane shago: abin da zai gudana, da yaushe. Ba ya canza komai.',
'Shp_G_Cmd2' => 'Dukkan tsarin shago ɗaya yanzu, ba tare da la’akari da agogo ba.',
'Shp_G_Cmd3' => 'Turawar kundin kaya ta farko: kayayyakin da ba a haɗa ba tukuna kawai.',
