'Shp_G_Cmd5' => 'Bi ta ciki kuma ka ba da rahoto, ba tare da rubuta komai a ko’ina ba.',
'Shp_Guide_Subtitle' => 'Haɗa shago, abin da ke gudana da kansa, da inda kowane saiti yake',
