'Agt_Tax_Map_Hint' => 'Ƙimomin da ba a lissafa ba ana aika su a matsayin OUT (Outra); 0% koyaushe ISE (Isento) ne.',
'Agt_Series' => 'Jerin lambobi',
'Agt_Series_Hint' => 'AGT tana ba da izinin jerin lambobi ɗaya ga kowane nau’in takarda, shekara da wurin kasuwanci. Ba za a iya fitar da rasitai ba sai da jerin lambobi mai aiki don nau’insu da shekararsu.',
'Agt_Request_Series' => 'Nemi jerin lambobi daga AGT',
'Agt_Add_Series' => 'Ƙara jerin lambobi da ke akwai',
'Agt_Contingency' => 'Na gaggawa (contingency)',
'Normal' => 'Na yau da kullum',
'Agt_Corrects' => 'Yana gyara',
'Agt_Late' => '> 24h',
'Agt_Check' => 'Duba',
'Agt_Correct_Confirm' => 'A fitar da gyara da sabuwar lamba don wannan takardar da aka ƙi?',
'Agt_Correct' => 'Gyara',
'Agt_Guide_What_Title' => 'Abin da wannan ke yi',
'Agt_Guide_What_Body' => 'Kowace siyarwa da aka kammala ana fitar da ita a matsayin rasitin lantarki na AGT (FR idan an biya lokacin ƙirƙira, in ba haka ba FT), kuma kowace mayarwa da aka karɓa a matsayin takardar rage bashi (NC). Kowace takarda tana samun lamba ta gaba a jerin lambobinta na AGT, ana sa mata hannu da mabuɗinku na AGT kuma ana aika ta zuwa AGT, wadda ke tantance ta bayan ’yan mintuna. Rasitin buga da rasitin PDF suna buga lambar AGT, guntun tsaro da lambar QR.',
'Agt_Guide_Steps_Title' => 'Saitawa',
'Agt_Guide_Step_1' => 'Shiga tsarin rasitin lantarki (adesão) a Portal do Contribuinte kuma sauke mabuɗin sirrinku na AGT.',
'Agt_Guide_Step_2' => 'Shigar da NIF ɗinku, wurin kasuwanci da mabuɗin a shafin Saituna, zaɓi Homologação, ajiye sannan yi amfani da Gwada Haɗin.',
'Agt_Guide_Step_3' => 'A shafin Jerin lambobi, nemi jerin lambobi ɗaya ga kowane nau’in takarda da kuke amfani da shi (FR, FT, NC) na shekarar yanzu.',
'Agt_Guide_Step_4' => 'Haɗa ƙimomin IVA ɗinku da lambobin AGT kuma saita lambar keɓewa don layukan 0%.',
'Agt_Guide_Step_5' => 'Kunna sashen a Saitunan Tsari > Fasali, yi siyarwar gwaji kuma duba cewa ta zama ingantacciya a shafin Takardu.',
'Agt_Guide_Step_6' => 'Idan AGT ta amince da ku don aiki na gaske, canja zuwa Produção kuma nemi jerin lambobin aiki na gaske.',
'Agt_Guide_Note_1' => 'Siyarwa ko mayarwa da aka riga aka aika ba za a iya gyarawa ko goge ta ba. Gyara ta da mayarwar siyarwa (takardar rage bashi).',
'Agt_Guide_Note_2' => 'Takardun da AGT ta ƙi ana gyara su da sabuwar lamba da ke nuni ga wadda aka ƙi; ba a sake amfani da tsohuwar lamba.',
'Agt_Guide_Note_3' => 'Siyarwar POS ta ba-intanet ana aika ta idan ta daidaita. AGT tana cin tarar takardun da aka aika bayan fiye da awa 24.',
'Agt_Guide_Note_4' => 'Layi ba zai iya ɗaukar harajin kaya da harajin oda tare ba; AGT tana buƙatar ƙimar IVA ɗaya a kowane layi. Ana aika jigilar kaya a matsayin layin da aka keɓe.',
'Agt_Guide_Note_5' => 'Jimillolin AGT ana lissafa su a kowane layi kuma za su iya bambanta da jimillar Stocky da ’yan kwabo saboda tattarawa.',
