'Dgi_Group' => 'Rukuni',
'Dgi_No_Documents' => 'Babu rasitan da aka tantance tukuna — tantancewa tana farawa da zarar haɗin e-MCF ya fara aiki.',
'Dgi_Guide_What_Title' => 'Abin da wannan ke yi a yau',
'Dgi_Guide_What_Body' => 'Idan sashen yana kunne, rasitai na buga da rasitan PDF suna buga NIF, RCCM da Id. Nat. na mai sayarwa da ake buƙata a kan facture normalisée. Cikakkiyar tantancewa (lambar DEF, ƙididdiga, lambar tabbatarwa da QR da DGI ke dawowa da su) za a ƙara ta da zarar an haɗa API na masu haɓaka e-MCF.',
'Dgi_Guide_Steps_Title' => 'Samun damar shiga e-MCF',
'Dgi_Guide_Step_1' => 'Ƙirƙiri asusu da NIF ɗinku a developper.dgirdc.cd kuma nemi damar shiga muhallin gwaji na e-MCF.',
'Dgi_Guide_Step_2' => 'Sauke takardun bayanin API (routes, DTOs, rukunan haraji) da bayanan shiga na gwaji.',
'Dgi_Guide_Step_3' => 'Aika su ga mai gudanar da dandalinku don a kammala haɗin kuma a gwada shi.',
'Dgi_Guide_Step_4' => 'Bayan gwaji, miƙa fayil ɗin homologation ga DGI.',
