'Variants_Options_Hint' => 'Ayyana zaɓuɓɓuka kamar Launi da Girma, sannan ƙirƙiri kowane haɗi. Kowane haɗi zai zama nau’i mai lambarsa, farashinsa da ajiyar kayansa.',
'Option_Name' => 'Sunan zaɓi',
'Option_Values_Placeholder' => 'Rubuta ƙima kuma danna Enter (misali Ja, Shuɗi)',
'Swatches' => 'Samfuran launi',
'Add_Option' => 'Ƙara zaɓi',
'Generate_Variants' => 'Ƙirƙiri nau’ikan',
'Apply_To_All' => 'Aiwatar ga duka',
'Variants_Guide' => 'Jagorar nau’ikan',
'VG_Intro' => 'Kaya mai nau’ikan ana sayar da shi a matsayin nau’ikan da yawa. Gina su daga zaɓuɓɓuka (an ba da shawara) ko a matsayin jeri mai sauƙi na sunaye. Kowane nau’i yana da lambarsa, farashinsa, hotonsa da ajiyar kayansa.',
'VG_Options_Title' => 'Yanayin zaɓuɓɓuka (Launi, Girma...)',
'VG_Opt_Step1' => 'Bar maɓallin da ke kan katin a kan "Zaɓuɓɓuka".',
'VG_Opt_Step2' => 'Rubuta sunan zaɓi kamar Launi ko Girma, ko zaɓi ɗaya daga cikin shawarwarin.',
'VG_Opt_Step3' => 'Rubuta ƙima (misali Ja) kuma danna Enter. Maimaita ga kowace ƙima; waƙafi ma yana raba ƙimomi. Danna x a kan ƙima don cire ta.',
'VG_Opt_Step4' => 'Danna "Ƙara zaɓi" don zaɓi na biyu ko na uku (zaɓuɓɓuka 3 ne iyaka).',
'VG_Opt_Step5' => 'Danna "Ƙirƙiri nau’ikan". Ana ƙirƙirar layi ɗaya ga kowane haɗi kuma ana gina sunansa ta atomatik, misali "Ja / S".',
'VG_Opt_Step6' => 'Shigar da farashin saye da farashin sayarwa a kowane layi, ko rubuta ƙima a "Aiwatar ga duka" kuma danna Farashin saye ko Farashi don kwafa ta zuwa kowane layi.',
'VG_Opt_Step7' => 'Ana ƙirƙirar lambobi muku. Rubuta naku ko danna alamar sabuntawa don ƙirƙirar wata.',
'VG_Opt_Step8' => 'Na zaɓi: yi alama a "Samfuran launi" a kan zaɓi kuma zaɓi launi ga kowace ƙima; shago yana nuna shi a matsayin ɗigo mai launi.',
'VG_Rows_Title' => 'Layukan nau’ikan',
'VG_Rows_Text' => 'Kowane layi yana da hoto, lamba, lambar ɗigo, farashin saye, farashi, farashin dillalai da mafi ƙarancin farashin sayarwa. Lokacin ƙirƙirar kaya za ku iya shigar da ajiyar kaya ta farko a kowane sito ga kowane nau’i. Alamar "Ba a kammala ba" tana nufin layin ba shi da ƙima ga wani zaɓi.',
'VG_List_Title' => 'Yanayin jeri mai sauƙi',
'VG_List_Text' => 'Rubuta sunan nau’i kuma danna Enter (ko danna Ƙara) don ƙara layi, sannan cike lambarsa da farashinsa. Wannan ita ce tsohuwar hanyar kuma tana nan don kayayyakin da ke akwai.',
'VG_Edit_Title' => 'Gyarawa daga baya',
'VG_Edit_1' => 'Ƙara ƙima kuma danna "Ƙirƙiri nau’ikan": haɗe-haɗen da babu su kawai ake ƙarawa. Layukan da ke akwai suna riƙe lambobinsu, farashinsu da tarihinsu.',
'VG_Edit_2' => 'Cire ƙima ko zaɓi yana cire layukan da ke amfani da shi. Layukan da aka riga aka ajiye ana goge su idan kun ajiye kayan, bayan tabbatarwa.',
'VG_Edit_3' => 'Nau’in da ke da sauran ajiyar kaya ba za a iya cire shi ba. Daidaita ko canja wurin ajiyar kayansa tukuna.',
'VG_Edit_4' => 'Canjawa zuwa "Jeri mai sauƙi" yana riƙe layukan da sunayensu amma yana cire ma’anonin zaɓuɓɓuka.',
'VG_Store_Title' => 'A shagon yanar gizo',
'VG_Store_Text' => 'Abokan ciniki suna zaɓar ƙima ɗaya ga kowane zaɓi, misali Launi sannan Girma. Haɗe-haɗen da babu su ana kashe su, waɗanda suka ƙare kuma ana ja musu layi. Nau’in da aka zaɓa shi ne ke shiga kwando.',
'Style' => 'Salo',
'Max_Options_Reached' => 'Kaya zai iya samun zaɓuɓɓuka 3 ne kawai a mafi yawa.',
'Variants_Removed' => 'An cire nau’ikan {count} masu kama da juna.',
'Remove_Option_Confirm' => 'A cire wannan zaɓin? Nau’ikan da suka bambanta ta shi kaɗai za a haɗa su.',
'Saved_Variants_Removed_On_Save' => 'Nau’ikan da aka ajiye waɗanda aka cire a nan za a goge su idan kun ajiye kayan.',
'Remove_Option_Values_Confirm' => 'Cire wannan ƙimar zai cire nau’ikan {count} da ke amfani da ita. A ci gaba?',
'Options_Required' => 'Ƙara aƙalla zaɓi ɗaya mai ƙimomi, ko canja zuwa jeri mai sauƙi.',
'Too_Many_Variants' => 'Nau’ikan sun yi yawa (iyaka {max}). Rage ƙimomin zaɓuɓɓuka.',
'Variants_Generated' => 'An ƙirƙiri nau’ikan {count}.',
'No_New_Combinations' => 'Dukkan haɗe-haɗe sun riga sun kasance.',
'Switch_To_List_Confirm' => 'A canja zuwa jeri mai sauƙi? Za a cire ma’anonin zaɓuɓɓuka; za a riƙe layukan nau’ikan.',
'Variant_Missing_Option_Values' => 'Kowane nau’i yana buƙatar ƙima ga kowane zaɓi.',
'Fashion_Theme' => 'Salon Kayan Sawa da Tufafi',
'Fashion_Theme_Hint' => 'Shagon tufafi irin na mujalla: kanun rubutu na serif, manyan hotuna, tayal na rukunoni, sababbin kayayyaki tare da shafukan rukunoni, banar lookbook da layin rangwame. Katunan kaya suna lissafa girma-girma (girman da ya ƙare ana ja masa layi) kuma suna canjawa zuwa hoto na biyu na gallery idan aka ɗora linzami. Ana amfani da babban launinku don farashin rangwame da alamomi. Slider na hero da banar lookbook suna bayyana da zarar kun ƙara su a ƙasa.',
