'Sale_Kicker' => 'Alamar rangwame',
'Sale_Title' => 'Taken rangwame',
'Show_Sizes_On_Cards' => 'Nuna girma-girma a katunan kaya',
'Card_Quick_Add' => 'Ƙari cikin sauri a katunan kaya',
'Fashion_Sizes_Hint' => 'Girma-girma suna fitowa daga zaɓin kaya mai suna "Size" (Kayayyaki > Zaɓuɓɓukan nau’i), ko daga sunayen nau’ikan kamar S, M, L ko 38. Kayayyakin da ke da zaɓin Girma kaɗai za a iya ƙara su cikin kwando kai tsaye daga katin.',
'Fashion_Category_Tiles_Auto' => 'Idan ba a ƙara tayal a ƙasa ba, nuna manyan rukunonina (tare da hoto daga kayayyakinsu)',
'Lookbook_Banners' => 'Banar lookbook',
'Size_Guides_Hint' => 'Jagorar girma tebur ne na girma-girma (tebur, hoto, ko duka biyun). Zaɓi ɗaya a kowane kaya (Kayayyaki > Gyara > Jagorar girma) kuma masu siyayya za su sami mahaɗin "Jagorar girma" a shafin kayan.',
'Size_Guide_Name_Placeholder' => 'misali Rigunan mata',
'Size_Guide_Image_Hint' => 'Na zaɓi. Ɗora hoton tebur (misali zanen yadda ake auna jiki). Jagora mai hoto kaɗai yana nuna wannan hoton a matsayin tebur.',
