'Column_Header' => 'Kanun shafi',
'Size_Guide_Columns_Hint' => 'Ƙara shafuka kamar Girma, Ƙirji, Ƙugu da Kwatangwalo, ko fara daga samfuri.',
'Size_Guide_Rows' => 'Layuka',
'Add_Row' => 'Ƙara layi',
'Size_Guide_No_Rows' => 'Babu layuka tukuna',
'Remove_Image' => 'Cire hoto',
'Size_Guide_Product_Hint' => 'Ana nuna shi a matsayin mahaɗin "Jagorar girma" a shafin kaya na shagon yanar gizo.',
'Select_Sales_Agent' => 'Zaɓi Wakilin Siyarwa',
'No_Sales_Agent' => 'Babu wakili',
'Pos_Sales_Agent_Hint' => 'Wakilin da aka zaɓa ne ke samun kwamishon wannan siyarwa. Idan babu wakili, kwamishon yana zuwa ga wakilin da aka haɗa da mai siyarwa.',
'Sold_By' => 'Wanda ya sayar',
'Auto_Sales_Agent' => 'Atomatik',
'Commission_Guide' => 'Jagorar Kwamisho',
'Comm_G_Intro_Title' => 'Yadda kwamisho ke aiki, a jimla ɗaya',
'Comm_G_Intro' => 'Idan aka ajiye siyarwar da aka kammala, dokokin da suka dace da wakilin siyarwa na siyarwar suna ƙirƙirar kwamisho masu matsayin Ana jira. Kuna amincewa da su a Rahoton Kwamisho kuma kuna biyan su da Rasidin Kwamisho. Idan siyarwar ta canza daga baya (biya, mayarwa, gyara, gogewa), ana sake lissafa kwamishonta ta atomatik.',
'Comm_G_Your_Setup' => 'Saitinku',
'Comm_G_Your_Setup_Help' => 'Matsayin wannan wurin aiki kai tsaye. Kowane mataki yana zama kore da zarar an yi shi.',
'Comm_G_Optional' => 'An ba da shawara',
'Comm_G_Step_Program' => 'Ƙirƙiri shirin kwamisho',
'Comm_G_Step_Program_Help' => 'Shiri yana tara dokokinku, misali "2026 Sales Team" ko "Summer Campaign". Dole ne ya kasance Mai aiki, kuma yau dole ta faɗa tsakanin ranakun Yana aiki Daga da Yana aiki Zuwa.',
'Comm_G_Step_Program_Warn' => 'Kuna da shirye-shirye, amma babu wanda ke aiki a yau. Duba akwatin Mai aiki da ranakun Yana aiki Daga / Yana aiki Zuwa.',
'Comm_G_Step_Agent' => 'Ƙara wakilan siyarwarku',
'Comm_G_Step_Agent_Help' => 'Wakilin siyarwa shi ne mutumin da ke samun kwamisho. Wakilai za su iya zama ma’aikata ko mutane na waje kamar masu kawo abokan ciniki ko dillalai.',
'Comm_G_Step_Link' => 'Haɗa wakilai da asusun masu amfani',
'Comm_G_Step_Link_Help' => 'Haɗa wakili da mai amfani yana bari a ba wakilin siyarwar da wannan mai amfani ya yi ta atomatik, ba tare da buƙatar zaɓar wakilin a kowace siyarwa ba.',
'Comm_G_Step_Link_Warn' => 'Wakilai {n} masu aiki ba a haɗa su da mai amfani ba. Suna samu ne kawai idan wani ya zaɓe su a siyarwa.',
'Comm_G_Step_Rule' => 'Ƙara aƙalla doka ɗaya',
'Comm_G_Step_Rule_Help' => 'Doka tana faɗin nawa za a biya, misali 5% na jimillar siyarwa. Dole ne ta kasance Mai aiki kuma ta kasance cikin shirin da ke aiki a yau.',
'Comm_G_Step_Rule_Warn' => 'Kuna da dokoki, amma babu wadda ke aiki a cikin shirin da ke aiki a yau.',
'Comm_G_Step_Sale' => 'Yi siyarwa da aka kammala',
'Comm_G_Step_Sale_Help' => 'Ana ƙirƙirar kwamisho idan aka ajiye siyarwar da aka kammala (Ƙirƙiri Siyarwa, Gyara Siyarwa ko POS). Siyarwar da aka yi kafin dokokinku su kasance ba a lissafa su.',
'Comm_G_Step_Sale_Done' => 'An lissafa kwamisho {n} zuwa yanzu.',
'Comm_G_Step_Approve' => 'Amince da kwamisho',
'Comm_G_Step_Approve_Help' => 'A Rahoton Kwamisho, yi alama a layukan Ana jira da kuka yarda da su kuma danna An amince. Babu abin da ke jira a yanzu.',
'Comm_G_Step_Approve_Warn' => 'Kwamisho {n} suna jiran amincewa.',
'Comm_G_Step_Pay' => 'Biya wakilanku',
'Comm_G_Step_Pay_Help' => 'A Rasidin Kwamisho, zaɓi wakili, yi alama a kwamishonsa da aka amince da su kuma ajiye rasidin. Za su zama An biya. Babu abin da ke jiran biya a yanzu.',
'Comm_G_Step_Pay_Warn' => 'Kwamisho {n} da aka amince da su suna jiran biya.',
'Comm_G_Try_Rule' => 'Gwada doka',
'Comm_G_Try_Rule_Help' => 'Shigar da siyarwa da doka don ganin ainihin abin da dokar za ta biya. Lissafin iri ɗaya ne da wanda tsarin ke amfani da shi.',
'Comm_G_Sale_Total' => 'Jimillar siyarwa',
'Comm_G_None' => 'Babu',
'Comm_G_Commission' => 'Kwamisho na wannan doka',
'Comm_G_No_Commission' => 'Babu kwamisho',
'Comm_G_Calc_Base' => 'Adadin tushe ({source}): {base}',
'Comm_G_Calc_Zero_Base' => 'Adadin tushe 0 ne, don haka wannan doka ba ta ƙirƙirar komai. Idan Adadin da aka Biya ne tushe, siyarwar da ba a biya ba ba ta samun komai har sai an rubuta biya.',
'Comm_G_Calc_Below_Min' => 'Tushen yana ƙasa da mafi ƙarancin iyaka na {min}, don haka wannan doka ba ta ƙirƙirar komai ga wannan siyarwa.',
'Comm_G_Calc_Pct' => '{value}% na {base} = {amount}',
'Comm_G_Calc_Fixed' => 'Ƙayyadadden adadi: {amount} a kowace siyarwa, ko yaya girman siyarwar yake',
'Comm_G_Calc_Capped' => 'Ya fi mafi girman iyaka, don haka an rage shi zuwa {cap}',
'Comm_G_Calc_Zero' => 'Sakamakon 0 ne, don haka ba a ƙirƙiri kwamisho ba.',
'Comm_G_The_Flow' => 'Tsarin aiki, mataki-mataki',
'Comm_G_Flow_Program' => 'Shiri',
'Comm_G_Flow_Program_Help' => 'Ƙirƙiri shiri kuma saita ranakun da yake aiki.',
'Comm_G_Flow_Agent' => 'Wakilan siyarwa',
'Comm_G_Flow_Agent_Help' => 'Ƙara mutanen da ke samun kwamisho kuma haɗa ma’aikata da asusunsu na masu amfani.',
'Comm_G_Flow_Rule' => 'Dokoki',
'Comm_G_Flow_Rule_Help' => 'A cikin shirin, ƙara dokoki: kaso ko ƙayyadadde, ga dukkan wakilai ko wakili ɗaya.',
'Comm_G_Flow_Sale' => 'Siyarwa',
'Comm_G_Flow_Sale_Help' => 'An ajiye siyarwar da aka kammala. Kowace doka da ta dace tana ƙirƙirar kwamisho ɗaya mai matsayin Ana jira.',
'Comm_G_Flow_Approve' => 'Amince',
'Comm_G_Flow_Approve_Help' => 'Duba kwamishon da ke Ana jira a Rahoton Kwamisho kuma amince da su ko soke su.',
'Comm_G_Flow_Pay' => 'Biya',
'Comm_G_Flow_Pay_Help' => 'Rubuta Rasidin Kwamisho ga wakilin. Kwamishon da ya ƙunsa suna zama An biya.',
'Comm_G_How_It_Works' => 'Yadda yake aiki',
'Comm_G_T_Credit' => 'Wane wakili ne ke samun kwamishon?',
'Comm_G_Credit_Intro' => 'Kowace siyarwa ana ba da ita ga wakili ɗaya a mafi yawa. Tsarin yana dubawa, a wannan tsari:',
'Comm_G_Credit_Picked' => 'Wakilin Siyarwa da aka zaɓa a siyarwar: filin Wakilin Siyarwa a Ƙirƙiri Siyarwa da Gyara Siyarwa, ko maɓallin "Wanda ya sayar" a POS. Idan an kashe wannan wakilin tun daga lokacin, siyarwar ba ta samun komai; ba ta komawa ga zaɓuɓɓuka na gaba.',
'Comm_G_Credit_Seller' => 'In ba haka ba, wakilin da aka haɗa da mai siyarwar da aka zaɓa a POS (idan maɓallin mai siyarwa na POS yana kunne).',
'Comm_G_Credit_Cashier' => 'In ba haka ba, wakilin da aka haɗa da mai amfanin da ya ajiye siyarwar.',
'Comm_G_Credit_Nobody' => 'Idan babu ɗaya daga cikin waɗannan da ya sami wakili mai aiki, siyarwar ba ta samun kwamisho.',
'Comm_G_Credit_Note' => 'A POS, barin wakili a kan "Atomatik" yana amfani da zaɓuɓɓuka na 2 da na 3. Sunan da ke nuna kusa da "Atomatik" shi ne wakilin da za a ba wa.',
'Comm_G_T_When' => 'Yaushe ake lissafa da sabunta kwamisho?',
'Comm_G_When_Intro' => 'Ana fara ƙirƙirar kwamisho idan aka ajiye siyarwa mai matsayin An kammala, a ɗaya daga cikin waɗannan wurare:',
'Comm_G_When_Create' => 'Ƙirƙiri Siyarwa: idan aka ajiye siyarwar a matsayin An kammala.',
'Comm_G_When_Edit' => 'Gyara Siyarwa: ajiye siyarwar da aka kammala yana sake lissafa ta daga farko da jimillarta, biyanta da wakilinta na yanzu, har da kwamishon da aka soke.',
'Comm_G_When_Pos' => 'POS: idan aka kammala siyarwa, har da daftarin da aka kammala daga baya.',
'Comm_G_When_Payment' => 'Ƙara biya ga siyarwar da aka kammala, wanda shi ne ke bari dokokin Adadin da aka Biya su kama biyan da aka karɓa bayan siyarwa.',
'Comm_G_When_Cod' => 'Biya bayan isarwa ta kamfanin isar da kaya: idan aka rubuta kuɗin da kamfanin isar da kaya ya karɓa a matsayin biya a kan siyarwar.',
'Comm_G_When_Not_Intro' => 'Waɗannan BA SA ƙirƙirar kwamisho:',
'Comm_G_When_Not_Status' => 'Siyarwar da aka ajiye a matsayin Ana jira ko An oda. Suna fara samu da zarar an gyara su kuma an ajiye su a matsayin An kammala.',
'Comm_G_When_Not_Before' => 'Siyarwar da aka ajiye kafin shirin ko dokar su kasance. Ba a lissafa su a bayan fage. Buɗe irin wannan siyarwa a Gyara Siyarwa da ajiye ta yana lissafa ta da dokokin da ke aiki a ranar siyarwar.',
'Comm_G_When_Not_Import' => 'Siyarwar da aka shigo da su daga fayil.',
'Comm_G_When_Not_Online' => 'Odar da aka yi a shagon yanar gizo.',
'Comm_G_T_Statuses' => 'Matsayin kwamisho',
'Comm_G_Meaning' => 'Abin da yake nufi',
'Comm_G_S_Pending' => 'An lissafa shi yanzu daga siyarwa. Babu wanda ya duba shi tukuna. Amince da shi ko soke shi a Rahoton Kwamisho.',
'Comm_G_S_Approved' => 'An duba kuma an yarda. Bashin wakilin ne kuma za a iya saka shi a Rasidin Kwamisho. Idan siyarwar ta canza kuma adadin ya canza, yana komawa Ana jira don sake dubawa.',
'Comm_G_S_Paid' => 'An saka shi a Rasidin Kwamisho. Na ƙarshe ne: ba a taɓa canza kwamishon da aka biya. Idan siyarwar ta canza daga baya, ana ƙara bambancin a matsayin Daidaitawa daban.',
'Comm_G_S_Cancelled' => 'Ba za a biya shi ba. Yana ci gaba da zama an soke idan biya ko mayarwa sun zo daga baya. Ajiye siyarwar a Gyara Siyarwa, ko yi masa alama a rahoton kuma danna Sake lissafawa, yana sake lissafa shi.',
'Comm_G_Field' => 'Fili',
'Comm_G_T_Programs' => 'Shirye-shiryen kwamisho',
'Comm_G_Programs_Body' => 'Shiri mazubi ne na dokoki, yawanci ɗaya ga kowane lokaci ko kamfe. Doka tana aiki ne kawai yayin da shirinta ke Mai aiki kuma ranar siyarwar ta faɗa cikin ranakun shirin. Shirye-shirye da yawa za su iya aiki a lokaci ɗaya, kuma dukkansu suna aiki.',
'Comm_G_F_Program_Name' => 'Duk sunan da zai taimaka muku gane shirin, misali "Q4 2026" ko "Black Friday".',
'Comm_G_F_Program_Active' => 'Cire alamar don dakatar da kowace doka a cikin shirin a lokaci ɗaya. Kwamishon da aka riga aka ƙirƙira ba ya shafar su.',
'Comm_G_F_Program_From' => 'Siyarwar da kwanan watanta ke kafin wannan rana shirin ba ya kula da ita. Bar shi babu komai idan babu ranar farawa.',
'Comm_G_F_Program_To' => 'Siyarwar da kwanan watanta ke bayan wannan rana shirin ba ya kula da ita. Bar shi babu komai don shirin da ba ya ƙarewa.',
'Comm_G_T_Agents' => 'Wakilan siyarwa',
'Comm_G_Agents_Body' => 'Wakilin siyarwa shi ne mutumin da ke samun kwamisho. Wakili ba lallai ne ya zama mai amfani da tsarin ba: masu kawo abokan ciniki ko dillalai na waje ma za su iya zama wakilai, kuma suna samu duk lokacin da aka zaɓe su a siyarwa.',
'Comm_G_F_Agent_Name' => 'Sunan da ke nunawa a siyarwa, rahoto da rasidai.',
'Comm_G_F_Agent_Code' => 'Lambar nuni ta zaɓi kamar lambar ma’aikaci. Ana iya neman ta a jerin wakilai.',
'Comm_G_F_Agent_User' => 'Yana haɗa wakilin da mai amfani na ma’aikata. Siyarwar da wannan mai amfani ya yi (ko aka zaɓe shi a matsayin mai siyarwa a POS) ana ba wa wannan wakilin ta atomatik.',
'Comm_G_F_Agent_Active' => 'Wakilai marasa aiki ba sa samun komai a sababbin siyarwa kuma suna ɓacewa daga masu zaɓar wakili. Kwamishonsu na baya yana nan.',
'Comm_G_T_Rules' => 'Dokokin kwamisho: bayanin kowane fili',
'Comm_G_Rules_Body' => 'Doka tana yanke hukuncin nawa za a biya a siyarwa. Yi amfani da akwatin "Gwada doka" da ke sama don duba doka kafin ku ajiye ta.',
'Comm_G_F_Rule_Program' => 'Shirin da dokar take ciki. Dokar tana aiki ne kawai yayin da wannan shirin ke aiki kuma cikin ranakunsa.',
'Comm_G_F_Rule_Type' => 'Kaso yana biyan rabo na adadin tushe. Ƙayyadadde yana biyan adadi ɗaya a kowace siyarwa da ta cancanta, ko yaya girmanta yake.',
'Comm_G_F_Rule_Source' => 'Abin da ake ɗaukar kason daga gare shi. Jimillar Siyarwa ita ce babbar jimillar siyarwar. Adadin da aka Biya shi ne abin da abokin ciniki ya biya lokacin da aka lissafa kwamishon.',
'Comm_G_F_Rule_Value' => 'Kason (5 yana nufin 5%) ko ƙayyadadden adadi, gwargwadon Nau’i.',
'Comm_G_F_Rule_Min' => 'Na zaɓi. Siyarwar da adadin tushenta ke ƙasa da wannan ba ta samun komai daga wannan doka. Siyarwar da ta yi daidai da iyakar tana samu.',
'Comm_G_F_Rule_Cap' => 'Na zaɓi. Mafi yawan abin da wannan doka za ta iya biya a siyarwa ɗaya. Yana aiki ga dokokin kaso da na ƙayyadadde.',
'Comm_G_F_Rule_Applies' => 'Dukkan Wakilai: kowane wakili yana samu daga wannan doka. Wakilin da aka ƙayyade: wakilin da kuka zaɓa kaɗai. Dokar Wakilin da aka ƙayyade da ba a zaɓi wakili ba ba ta taɓa biyan kowa.',
'Comm_G_F_Rule_Priority' => 'A shirin da aka saita zuwa "Doka mafi fifiko kaɗai ke biya", dokar da ta cancanta mai lamba mafi girma ce ke cin nasara, sauran kuma ana tsallake su. Idan sun yi kunnen doki, dokar Wakilin da aka ƙayyade tana rinjayar dokar Dukkan Wakilai. A shirin da aka saita zuwa "Kowace doka da ta dace tana biya", Fifiko yana saita tsari ne kawai.',
'Comm_G_F_Rule_Active' => 'Cire alamar don dakatar da wannan doka ɗaya. Kwamishon da ta riga ta ƙirƙira ba ya shafar su.',
'Comm_G_T_Stacking' => 'Dokoki da yawa a siyarwa ɗaya',
'Comm_G_Stacking_Body' => 'Kowane shiri yana yanke hukuncin yadda dokokinsa ke haɗuwa (saitin "Idan dokoki da yawa sun dace" a kan shirin).

Doka mafi fifiko kaɗai ke biya (na asali ga sababbin shirye-shirye): ana gwada dokoki daga Fifiko mafi girma zuwa ƙasa, kuma ta farko da ta cancanta ga siyarwar ce ke biya. Doka tana cancanta idan siyarwar ta kai mafi ƙarancin iyakarta kuma sakamakon ya fi 0. Wannan yana sauƙaƙa matakai: "7% a kan siyarwar 10,000 ko fiye" a fifiko 10 da "5%" a fifiko 0. Don ba Sara ƙima ta musamman, ƙara mata dokar Wakilin da aka ƙayyade mai fifiko sama da dokar Dukkan Wakilai.

Kowace doka da ta dace tana biya: dukkan dokokin da suka dace suna biya kuma adadin yana haɗuwa. Dokar Dukkan Wakilai ta 3% tare da dokar Wakilin da aka ƙayyade ta 2% ga Sara tana ba Sara 5%.

Shirye-shirye sun rabu da juna: kowane shiri mai aiki yana biya da kansa, don haka siyarwa za ta iya samu daga shiri na asali da shirin kamfe a lokaci ɗaya.',
'Comm_G_T_Paying' => 'Biyan wakilai da Rasidin Kwamisho',
'Comm_G_Paying_Body' => 'Buɗe Rasidin Kwamisho kuma danna Ƙara. Zaɓi wakilin: ana lissafa kwamishonsa da aka amince da su. Yi alama a waɗanda kuke biya; Adadi yana cikewa da jimillarsu, kuma za ku iya daidaita shi. Ana cike Lambar ref. ta atomatik (CR-000001, CR-000002...), kuma za ku iya ƙara hanyar biya, kwanan wata da bayani.

Ajiye rasidin yana sanya kwamishon da aka yi wa alama a matsayin An biya kuma yana haɗa su da rasidin. Kwamishon da aka amince da su kaɗai za a iya biya, don haka ku fara amince da su a Rahoton Kwamisho.

Daidaitawa na ragi (kuɗin da aka biya wakilin fiye da haka) ma ana lissafa su. Yi musu alama tare da kwamishon wakilin na gaba don a cire su daga wannan biyan.

Rasidi rikodi ne na biyan kawai: ba ya ƙirƙirar kuɗaɗen fita ko motsa kuɗi a asusunku. Idan kuna bin diddigin biyan a Kuɗaɗen fita ko Lissafin kuɗi, ku rubuta su a can ma.',
'Comm_G_T_Snapshot' => 'Idan siyarwa ta canza',
'Comm_G_Snapshot_Body' => 'Kwamisho yana bin siyarwa. Duk lokacin da siyarwa mai kwamisho ta canza, ana sake lissafa su daga alƙaluman ta na yanzu: jimillar siyarwa ban da mayarwar da aka karɓa, da adadin da aka biya ban da kuɗin da aka mayar.

Kwamishon da ba a biya ba (Ana jira ko An amince) ana sabunta su kawai. Kwamishon da aka amince da shi wanda adadinsa ya canza yana komawa Ana jira don wani ya sake duba shi. Wanda ba a bin bashinsa yanzu (an goge siyarwa, an mayar da duka, an canza wakili) ana cire shi.

Ba a taɓa canza kwamishon da aka biya. Bambancin yana zama sabon layi mai matsayin Ana jira mai alamar Daidaitawa: na ƙari idan ana bin ƙarin bashi (misali an biya sauran siyarwar Adadin da aka Biya), na ragi idan an biya wakilin fiye da haka (misali bayan mayarwa). Amince da shi kuma saka shi a rasidin wakilin na gaba.

Kowane kwamisho yana riƙe sharuɗɗan dokar (nau’i, ƙima, iyaka, mafi girman iyaka) tun lokacin da aka fara samun shi. Canza ko kashe doka daga baya ba ya sake farashin tsofaffin siyarwa idan aka sake lissafa su.',
'Comm_G_T_Permissions' => 'Wane ne zai iya yin me',
'Comm_G_Permission' => 'Izini',
'Comm_G_Lets_You' => 'Abin da yake ba da dama',
'Comm_G_P_View' => 'Ganin dukkan shafukan Kwamisho: shirye-shirye, wakilai, dokoki, rasidai, rahoto da wannan jagorar.',
'Comm_G_P_Add' => 'Ƙirƙirar shirye-shirye, wakilai da dokoki, da rubuta Rasidin Kwamisho (biyan wakilai).',
'Comm_G_P_Edit' => 'Gyara shirye-shirye, wakilai da dokoki, da amincewa ko soke kwamisho a Rahoton Kwamisho.',
'Comm_G_P_Delete' => 'Goge shirye-shirye, wakilai da dokoki.',
'Comm_G_T_Faq' => 'Tambayoyi da amsoshi',
'Comm_G_Q_Empty' => 'Na saita komai amma Rahoton Kwamisho babu komai a ciki.',
'Comm_G_A_Empty' => 'Duba cewa: an ajiye siyarwar bayan an ƙirƙiri dokar; siyarwar An kammala ce; siyarwar tana da wakili (an zaɓe shi a siyarwar, ko mai amfanin da ya yi ta an haɗa shi da wakili); shirin yana aiki kuma ranar siyarwar tana cikin ranakunsa; dokar tana aiki kuma ta shafi wannan wakilin; kuma siyarwar ta kai ko ta wuce mafi ƙarancin iyakar dokar. Haka kuma duba matatar kwanan wata na rahoton: tana tacewa ne bisa ranar da aka lissafa kwamishon.',
'Comm_G_Q_Twice' => 'Wakili ya sami kwamisho biyu a siyarwa ɗaya.',
'Comm_G_A_Twice' => 'Dokoki biyu sun biya: ko dai an saita shirin zuwa "Kowace doka da ta dace tana biya", ko dokokin suna cikin shirye-shirye biyu daban masu aiki (kowane shiri yana biya da kansa). Saita shirin zuwa "Doka mafi fifiko kaɗai ke biya" idan ɗaya kaɗai ya kamata ya biya. Sake ajiye siyarwa ba ya taɓa ninka kwamisho.',
'Comm_G_Q_Rate' => 'Idan na canza ƙimar doka, tsofaffin kwamisho za su canza?',
'Comm_G_A_Rate' => 'A’a. Kowane kwamisho yana riƙe sharuɗɗan dokar da aka same shi a ƙarƙashinta, ko da an sake lissafa siyarwarsa daga baya. Ana amfani da sabuwar ƙimar don kwamishon da za a samu daga yanzu.',
'Comm_G_Q_Return' => 'Abokin ciniki ya mayar da kayan. Me zai faru da kwamishon?',
'Comm_G_A_Return' => 'Ana rage shi ta atomatik. Mayarwar da aka karɓa tana rage jimillar siyarwa, kuma mayar da kuɗi yana rage adadin da aka biya. Idan ba a biya kwamishon ba tukuna, ana sabunta shi (ko a cire shi idan an mayar da duka). Idan an riga an biya shi, ana ƙara Daidaitawa ta ragi kuma ana cire ta daga rasidin wakilin na gaba.',
'Comm_G_Q_Wrong_Agent' => 'Na ba wa wakilin da ba daidai ba. Ta yaya zan gyara?',
'Comm_G_A_Wrong_Agent' => 'Gyara siyarwar, zaɓi Wakilin Siyarwa daidai kuma ajiye. Kwamishon yana komawa ga wakilin da ya dace. Idan an riga an biya wakili na farko, ana ƙara masa Daidaitawa ta ragi.',
'Comm_G_Q_Inactive' => 'Me ke faruwa idan na kashe wakili?',
'Comm_G_A_Inactive' => 'Yana daina samu a sababbin siyarwa kuma ana ɓoye shi daga masu zaɓar wakili. Kwamishonsa da ke akwai yana nan, za a iya amincewa da shi kuma a biya shi, kuma yana ci gaba da bin canje-canjen siyarwarsa. Siyarwar da aka ajiye da wannan wakilin a zaɓe ba za ta koma ga wani wakili ba.',
'Comm_G_Q_Partial' => 'Ta yaya dokokin Adadin da aka Biya ke sarrafa biyan kashi-kashi?',
'Comm_G_A_Partial' => 'Siyarwar da ba a biya ba ba ta samun komai. Ana ƙirƙirar kwamishon idan aka fara karɓar kuɗi (a lokacin biya ko lokacin da aka ƙara biya) kuma yana ƙaruwa yayin da ƙarin biya ke shigowa. Idan an riga an biya wani ɓangare nasa, sauran yana zuwa a matsayin Daidaitawa ta ƙari.',
'Comm_G_Q_Undo' => 'Zan iya soke biya ko sokewa?',
'Comm_G_A_Undo' => 'Biya, a’a: An biya na ƙarshe ne kuma ba za a iya gyara ko goge rasidai ba, don haka ku duba kwamishon da aka yi wa alama da adadin kafin ajiyewa. Sokewa, eh: yi alama a layin a Rahoton Kwamisho kuma danna Sake lissafawa, ko sake ajiye siyarwar a Gyara Siyarwa.',
'Comm_G_Q_Dates' => 'Wace rana ce ranakun shirin ke amfani da ita?',
'Comm_G_A_Dates' => 'Ainihin kwanan watan siyarwar, ba ranar da aka ajiye ta ba. Siyarwa mai kwanan watan watan jiya tana amfani ne kawai da shirye-shiryen da suka yi aiki a watan jiya.',
'Comm_G_When_Changes' => 'Daga baya, duk wani canji ga siyarwar da ke da kwamisho yana sabunta su da kansa: biyan da aka gyara ko goge, mayarwa da mayar da kuɗi, matsayi ya bar An kammala, ko an goge siyarwar.',
'Comm_G_F_Program_Mode' => 'Abin da ke faruwa idan dokoki da yawa a wannan shirin sun dace da siyarwa ɗaya. "Doka mafi fifiko kaɗai ke biya": ana gwada dokoki daga Fifiko mafi girma zuwa ƙasa kuma ta farko da ta cancanta ce ke biya. "Kowace doka da ta dace tana biya": dukkansu suna biya kuma adadin yana haɗuwa.',
'Comm_G_Q_Mode_Old' => 'Na saita fifiko, amma dokoki har yanzu suna haɗuwa.',
'Comm_G_A_Mode_Old' => 'An saita wannan shirin zuwa "Kowace doka da ta dace tana biya". Shirye-shiryen da aka ƙirƙira kafin wannan saitin ya kasance suna riƙe wannan halin don kada biyansu ya canza. Gyara shirin kuma zaɓi "Doka mafi fifiko kaɗai ke biya".',
'Comm_G_Q_Negative' => 'Me yasa akwai kwamisho na ragi (ƙasa da sifili)?',
'Comm_G_A_Negative' => 'Daidaitawa ce: an biya wakilin fiye da abin da siyarwar ke samarwa yanzu, saboda mayarwa, mayar da kuɗi, jimilla ƙasa da ta baya, canjin wakili ko goge siyarwa. Amince da ita kuma yi mata alama a rasidin wakilin na gaba don a cire ta.',
'Comm_Rule_Mode' => 'Idan dokoki da yawa sun dace',
'Comm_Mode_Highest' => 'Doka mafi fifiko kaɗai ke biya',
'Comm_Mode_All' => 'Kowace doka da ta dace tana biya (suna haɗuwa)',
'Comm_Mode_Highest_Short' => 'Mafi fifiko ke cin nasara',
'Comm_Mode_All_Short' => 'Dokoki suna haɗuwa',
'Comm_Mode_Highest_Help' => 'Ana gwada dokoki daga Fifiko mafi girma zuwa ƙasa; ta farko da ta cancanta ga siyarwar ce ke biya, sauran kuma ana tsallake su. Yana da kyau ga matakai, misali 7% sama da 10,000 a fifiko 10 da 5% ga duk sauran a fifiko 0.',
'Comm_Mode_All_Help' => 'Kowace doka da ta dace da wakilin tana biya a siyarwar, don haka adadin yana haɗuwa. Fifiko yana saita tsari ne kawai.',
'Comm_Priority_Help_Highest' => 'Wannan shirin yana biyan doka mafi fifiko da ta cancanta kaɗai. Ba wannan doka Fifiko sama da dokokin da ya kamata ta rinjaya. Idan sun yi kunnen doki, dokar Wakilin da aka ƙayyade tana rinjayar dokar Dukkan Wakilai.',
'Comm_Priority_Help_All' => 'Wannan shirin yana biyan kowace doka da ta dace, don haka wannan doka tana ƙaruwa a kan sauran. Fifiko yana saita tsari ne kawai.',
'Comm_Recalculate' => 'Sake lissafawa',
'Comm_Recalculate_Help' => 'Yana sake lissafa siyarwar layukan da aka yi wa alama daga alƙaluman su na yanzu, har da kwamishon da aka soke.',
'Comm_Adjustment' => 'Daidaitawa',
'Comm_Adjustment_Help' => 'Gyara ga kwamishon da aka riga aka biya, saboda siyarwar ta canza daga baya. Adadi na ragi (ƙasa da sifili) ana cire shi daga rasidin wakilin na gaba.',
'Comm_Cancel_Confirm' => 'A soke kwamishon da aka zaɓa?',
'Comm_Cancel_Confirm_Help' => 'Ba za a biya su ba, kuma za su ci gaba da zama an soke idan biya ko mayarwa sun zo daga baya. Ajiye siyarwar a Gyara Siyarwa ko danna Sake lissafawa yana sake lissafa su.',
'Fashion_Tiles_Hint' => 'Ƙara tayal ɗinku (hoto, take da mahaɗi) don maye gurbin tayal na rukunoni na atomatik.',

