'Rst_Guide_Step_Booking_Help' => 'Bari baƙi su ajiye tebur daga shagon yanar gizo. Saita sa’o’in ajiya, tazara da mafi girman rukuni a Saitunan Gidan Abinci.',
'Rst_Guide_Step_Store' => 'Shagon yanar gizo da salon Gidan Abinci',
'Rst_Guide_Step_Store_On' => 'Salon Gidan Abinci yana aiki. Odocin yanar gizo suna kaiwa kicin: {mode}.',
'Rst_Guide_Step_Store_Help' => 'A Shagon yanar gizo › Saituna zaɓi salon "Gidan Abinci": shafin farko zai zama menu ɗinka, tare da ƙare-ƙare, ɗauka / kai wa gida da ajiyar tebur.',
'Rst_Guide_How' => 'Yadda yake aiki',
'Rst_Guide_Service' => 'Hidima, mataki-mataki',
'Rst_Guide_Service_1_T' => 'Zaunarwa',
'Rst_Guide_Service_1' => 'A taswirar zaure zaɓi tebur da babu kowa, shigar da yawan baƙi da mai hidima, sannan "Zaunar da baƙi kuma karɓi oda". Ana zaunar da rukunin da ya yi ajiya daga ajiyarsa.',
'Rst_Guide_Service_2_T' => 'Oda',
'Rst_Guide_Service_2' => 'Taɓa abinci a allon oda. Zaɓi ƙare-ƙare, kujera da zagaye; ƙara bayani ga kicin. Dakatar da zagaye don fara shi daga baya.',
'Rst_Guide_Service_3_T' => 'Aikawa',
'Rst_Guide_Service_3' => '"Aika" yana sanya sabbin abinci a tikitin kicin ɗaya. Abincin da ba a aika ba tukuna ana iya canza su ko cire su; bayan haka ana iya janye su ne kawai tare da dalili.',
'Rst_Guide_Service_4_T' => 'Dafawa',
'Rst_Guide_Service_4' => 'Allon kicin yana nuna tikitin a kowane sashe. Masu dafa abinci suna fara shi, suna yi wa abinci alama yayin da suka gama kuma suna kammala shi idan komai ya shirya.',
'Rst_Guide_Service_5_T' => 'Kai wa',
'Rst_Guide_Service_5' => 'Abincin da suka shirya suna bayyana a taswirar zaure da allon oda. Mai hidima yana kai su kuma ya taɓa "Yi alama an kai".',
'Rst_Guide_Service_6_T' => 'Lissafi',
'Rst_Guide_Service_6' => '"Lissafi & biya" yana buga lissafin kuɗi kuma ya karɓi biya: lissafi gaba ɗaya, raba daidai ko bisa abu. Kowane biya siyarwar POS ce ta yau da kullum.',
'Rst_Guide_Service_7_T' => 'Sharewa',
'Rst_Guide_Service_7' => 'Idan an biya komai odar tana rufe kuma tebur ya zama "Yana buƙatar tsaftacewa" (ko kai tsaye babu kowa, bisa Saitunan Gidan Abinci).',
'Rst_Guide_Roles' => 'Wa ke yin me',
'Rst_Guide_Roles_Help' => 'Ana ba da izinin gidan abinci bisa matsayi a Izinin Rukuni. Mai amfani zai iya samun izinin matsayi da yawa.',
'Rst_Guide_Job' => 'Aiki',
'Rst_Guide_Give' => 'Ba da waɗannan izini',
'Rst_Guide_Job_Waiter' => 'Mai hidima',
'Rst_Guide_Job_Cook' => 'Mai dafa abinci',
'Rst_Guide_Job_Cashier' => 'Mai karɓar kuɗi',
'Rst_Guide_Job_Host' => 'Mai karɓar baƙi / teburin gaba',
'Rst_Guide_Job_Supervisor' => 'Mai sa ido',
'Rst_Guide_Job_Manager' => 'Manaja',
'Rst_Guide_Menu' => 'Menu, sassa da ƙare-ƙare',
'Rst_Guide_Menu_1' => 'Kowane kaya da kake sayarwa zai iya zama abinci. Gidan Abinci › Menu (ko katin "Bayanan abinci" a fom ɗin kaya) yana ƙara bayanan gidan abinci.',
'Rst_Guide_Menu_2' => 'Rukunin ƙare-ƙare suna ɗauke da zaɓuɓɓuka masu farashi: "Girma" (zaɓi 1) ko "Ƙari" (har 3). Ana duba ƙa’idodin a kowace oda, har da ta yanar gizo.',
'Rst_Guide_Menu_3' => 'Ƙari zai iya amfani da kayan haɗi: haɗa "Ƙarin cuku" da kayanka na Cuku kuma kowane ɗaya zai cire daga ajiyar kayan.',
'Rst_Guide_Menu_4' => 'Yi wa abinci alama ya ƙare na yau da maɓalli ɗaya; zai dawo gobe da kansa. Lokutan cin abinci (karin kumallo, rana, dare) suna iyakance lokacin da ake bayar da abinci.',
'Rst_Guide_Menu_5' => 'Girke-girke kaya ne na combo: idan ajiyar combo ta kama-da-wane a kunne, sayar da abincin yana cire kayan haɗinsa daga ajiyar kaya.',
'Rst_Guide_Kitchen' => 'Allon kicin',
'Rst_Guide_Kitchen_1' => 'Buɗe Gidan Abinci › Kicin a wani allo a kicin. Zaɓi sashe; abincin da ba su da sashe suna bayyana a kowane sashe.',
'Rst_Guide_Kitchen_2' => 'Tikiti suna komawa ruwan ɗorawa sannan ja yayin da suke jira (Saitunan Gidan Abinci › ya makara bayan minti N). Ƙara tana sanar da sabbin tikiti.',
'Rst_Guide_Kitchen_3' => 'Fara → yi wa abinci alama → Kammala. "An gama a wannan sashe" yana kammala abincin wannan sashe kawai a kan tikitin da aka raba.',
'Rst_Guide_Kitchen_4' => 'Tikitin da aka kai suna zama na minti 15 don a iya dawo da kuskure. Ana iya buga tikiti a firinta na 80 mm.',
'Rst_Guide_Kitchen_5' => 'Odoci daga shagon yanar gizo da daga lambobin QR na tebur ana yi musu alama "Yanar gizo" ko "QR" a tikitinsu.',
'Rst_Guide_Bills' => 'Lissafin kuɗi da biya',
'Rst_Guide_Bills_1' => 'Kowane biya siyarwar POS ce ta yau da kullum: ajiyar kaya, akwatin kuɗi, lissafin kuɗi (accounting), makin aminci da rasitin lantarki suna aiki kamar a POS.',
'Rst_Guide_Bills_2' => 'Kuɗin hidima kashi ne na abinci kafin haraji, don ci a nan (ko kowace oda, bisa saitinka). Tukwici kashi ne da aka saita ko adadi.',
'Rst_Guide_Bills_3' => 'Ragi yana buƙatar izinin "Ba da ragi a kan lissafin kuɗi" kuma ba zai wuce mafi girman ragi a Saitunan Gidan Abinci ba.',
'Rst_Guide_Bills_4' => 'Zagayawa yana sauka zuwa matakinka, don amfanin baƙo, a kan biyan da ya kammala lissafin kuɗi.',
'Rst_Guide_Bills_5' => 'Raba daidai: siyarwa ɗaya, layin biya ɗaya ga kowane mutum (rabo har zuwa kwabo). Raba bisa abu: abincin kowane baƙo suna zama siyarwarsa ta daban; zaɓi kujera don zaɓar abincinta.',
'Rst_Guide_Bills_6' => 'Idan lissafin kuɗi ya canza bayan an nuna shi (an ƙara abinci daga lambar QR, an canza tukwici), ana ƙin biyan don kada a taɓa cajin baƙo kan abin da bai gani ba.',
'Rst_Guide_Bills_7' => 'Ba za a iya janye abincin da aka biya ba. Idan an janye ragowar oda da ba a biya ba, odar tana rufe a matsayin an biya kuma za a iya share tebur.',
'Rst_Guide_Bookings' => 'Ajiyar wuri da jerin jira',
'Rst_Guide_Bookings_1' => 'Ajiyoyi suna riƙe tebur tsawon lokacinsu (na asali a Saitunan Gidan Abinci). Ajiyoyi biyu ba za su taɓa haɗuwa a kan tebur ɗaya ba.',
'Rst_Guide_Bookings_2' => 'Taswirar zaure tana nuna ajiyar gaba ta kowane tebur kuma tana gargaɗi idan lokacinta ya kusa; "Sun iso — zaunar" yana zaunar da rukunin.',
'Rst_Guide_Bookings_3' => 'Bayan lokacin rashin zuwa ana iya yi wa rukunin da ya makara alama cewa bai zo ba; ana iya maido da kuskure.',
'Rst_Guide_Bookings_4' => 'Jerin jira yana riƙe waɗanda suka zo kai tsaye bisa tsari tare da lokacin jiran da aka faɗa musu. Kira su ko tura musu WhatsApp idan tebur ya shirya, sannan ka zaunar da su.',
'Rst_Guide_Bookings_5' => 'Ajiyoyin yanar gizo suna isowa a matsayin "An ajiye" (alama a sidebar tana ƙirga su) don ka tabbatar.',
'Rst_Guide_Online' => 'Odocin yanar gizo, menu na QR da ajiya ta yanar gizo',
'Rst_Guide_Online_1' => 'Da salon shagon Gidan Abinci, shafin farko na shagon yanar gizo shi ne menu ɗinka, tare da ƙare-ƙare da matatun irin abinci; masu siyayya suna biya a wurin biya kamar yadda aka saba.',
'Rst_Guide_Online_2' => '"Odocin yanar gizo suna zuwa kicin" yana yanke lokacin da suke kaiwa allon kicin: idan an yi oda (an biya, ko abokin ciniki da ya shiga yana biya idan an kawo / an ɗauka), idan an karɓa, ko ba zai taɓa ba.',
'Rst_Guide_Online_3' => 'Lambobin QR na tebur (Shirya zaure › Lambobin QR na teburori) suna buɗe menu don wannan tebur. "Sabon link" yana soke lambar da aka buga.',
'Rst_Guide_Online_4' => 'Odocin QR suna jira a kan odar tebur har mai hidima ya aika su, sai dai idan "Aika odocin QR kai tsaye zuwa kicin" yana kunne. Baƙi suna biya ta hannun ma’aikata.',
'Rst_Guide_Online_5' => 'Ajiya ta yanar gizo tana bayar da lokuta ne kawai idan akwai tebur da ya isa rukunin kuma babu kowa a kansa tsawon ajiyar gaba ɗaya, kuma tana iyakance kowace lambar waya zuwa ajiyoyi 3 masu zuwa.',
'Rst_Guide_Online_6' => 'Duk wannan ɓangare ne na shagon yanar gizo: dole ne a kunna shi kuma ya kasance cikin shirinka.',
'Rst_Guide_Reports' => 'Dashboard da rahotanni',
'Rst_Guide_Reports_1' => 'Dashboard yana nuna yau idan aka kwatanta da wannan rana makon jiya: siyarwa, lissafin kuɗi, baƙi, matsakaicin lissafi, janyewa da ragi, da abin da ke faruwa yanzu haka.',
'Rst_Guide_Reports_2' => 'Siyarwa ita ce lissafin kuɗin gidan abinci da odocin yanar gizo da suka kai kicin. Siyarwar abinci da riba kafin haraji ne, ta amfani da farashin kowane kaya.',
'Rst_Guide_Reports_3' => 'Rahotanni: siyarwa bisa rana da hanyar biya, abinci, janyewa da sokewa (tare da dalilai), ma’aikata, lokutan kicin da ajiyar wuri — kowanne yana fitarwa zuwa Excel.',
'Rst_Guide_Reports_4' => 'Ma’aikatan da aka iyakance ga wasu rassa suna ganin rassansu kawai; odocin da ba su da reshe na kowa ne.',
'Rst_Guide_Faq' => 'Abin da ya kamata ka sani',
'Rst_Guide_Faq_1_Q' => 'An biya odar ɗauka a tafi kafin na danna "Aika". Za a dafa ta?',
'Rst_Guide_Faq_1_A' => 'Ee. Biya yana aika duk abincin da ba a aika ba tukuna zuwa kicin.',
'Rst_Guide_Faq_2_Q' => 'Me ya sa ba zan iya share tebur ba?',
'Rst_Guide_Faq_2_A' => 'Odarsa har yanzu tana da abincin da ba a biya ba. Karɓi biya, janye abin da ba a ci ba, ko soke odar (sai dai idan ba a biya komai ba tukuna).',
'Rst_Guide_Faq_3_Q' => 'An haɗa teburori biyu wuri ɗaya. Me zai faru da odocinsu?',
'Rst_Guide_Faq_3_A' => '"Haɗa teburori" yana matsar da abincin tebur na biyu (da duk wani biya) zuwa odar babban tebur; "Raba wannan tebur" yana sake raba teburorin.',
'Rst_Guide_Faq_4_Q' => 'Shin biyan kati zai iya amfani da Stripe a nan?',
'Rst_Guide_Faq_4_A' => 'A’a. Biyan kati na Stripe yana buƙatar fom ɗin kati na POS; don na’urar kati ƙara hanyar biya kamar "Kati" kuma ka yi amfani da ita a lissafin kuɗi.',
'Rst_Guide_Faq_5_Q' => 'Wani abinci ya ƙare a reshe ɗaya kawai.',
'Rst_Guide_Faq_5_A' => 'Ana cire ajiyar kaya daga reshen oda (sashen tebur, ko kuma reshe na asali a Saitunan Gidan Abinci). Yi amfani da "Ya ƙare yau" don dakatar da oda da sauri.',
'Rst_Guide_Faq_6_Q' => 'Ina buƙatar firinta?',
'Rst_Guide_Faq_6_A' => 'A’a. Lissafin kuɗi, rasiti da tikitin kicin suna bugawa daga browser a kowane firinta; firintocin rasiti na 80 mm sun fi dacewa.',
'Rst_Guide_Faq_7_Q' => 'Daga ina menu na gidan abinci ke fitowa a shagon yanar gizo?',
'Rst_Guide_Faq_7_A' => 'Daga kayayyaki, rukunoni da ƙare-ƙare iri ɗaya. Kayayyakin da aka ɓoye daga shagon yanar gizo, da rukunonin da ba a nuna a shagon, ba sa bayyana a menu na yanar gizo da menu na QR.',

// Rental — business types + website booking (Rental store theme).
'Rental_Website_Not_Ready' => 'Girka sabuntawa ta baya-bayan nan don amfani da nau’ukan kasuwanci da ajiya ta shafin yanar gizo.',
'Rental_Business_Type' => 'Nau’in kasuwanci',
'Rental_Business_Type_Help' => 'Yi alama a kan abin da kake bayarwa haya. Fom ɗin abu, rukunoni, matatu da shafin yanar gizonka za su nuna waɗannan nau’ukan da filayensu kawai.',
'Rental_Business_Type_All' => 'Ba a yi alama a kan komai ba: kowane nau’i yana samuwa.',
'Rental_Website_Booking' => 'Ajiya ta shafin yanar gizo',
'Rental_Website_Theme_Off' => 'Shagon yanar gizonka yana amfani da wani salo. Zaɓi salon Haya a saitunan Shago don wallafa abubuwan hayarka.',
'Rental_Open_Store_Settings' => 'Buɗe saitunan Shago',
'Rental_Website_Booking_Help' => 'Masu ziyara suna zaɓar kwanaki a shafin yanar gizonka kuma suna aika buƙatar ajiya. Tana isowa a Ajiyar wuri a matsayin riƙo: tabbatar da ita, mayar da ita kwangila ko soke ta.',
'Rental_Website_Hold' => 'Riƙe buƙata tsawon',
'Rental_Website_Hold_Help' => 'Abubuwan suna kasancewa a toshe tsawon wannan lokaci yayin da kake amsawa. Tabbatarwa tana riƙe su har ƙarshen hayar.',
'Rental_Website_Notice' => 'Mafi ƙarancin sanarwa',
'Rental_Website_Notice_Help' => 'Yadda ajiya ta shafin yanar gizo za ta iya farawa da wuri.',
'Rental_Website_Ahead' => 'Ajiya har zuwa',
'Rental_Website_Ahead_Help' => 'Yadda masu ziyara za su iya yin ajiya nesa a gaba.',
'Rental_Website_Login' => 'Dole a shiga',
'Rental_Website_Login_Help' => 'Abokan ciniki masu asusun shago ne kawai za su iya aika buƙatu.',
'Rental_Pickup_Locations' => 'Wuraren ɗauka',
'Rental_Pickup_Locations_Help' => 'Ababen hawa: wuraren da abokan ciniki za su iya zaɓa don ɗauka da mayarwa. Bar shi babu komai idan ana ɗaukar komai a reshenka.',
'Rental_Pickup_Locations_Placeholder' => 'misali Filin jirgin sama; Ofishin tsakiyar gari',
'Rental_Booking_Form_Fields' => 'Filayen fom ɗin ajiya',
'Rental_Booking_Form_Fields_Help' => 'Abin da fom ɗin ajiya na shafin yanar gizo ke tambaya, bisa nau’in kasuwanci. Ana tambayar suna, waya da imel koyaushe.',
'Rental_Field_Location_Hint' => 'Ana nuna shi ne kawai idan an saita wuraren ɗauka.',
'Rental_Website_Terms' => 'Sharuɗɗan haya a shafin yanar gizo',
'Rental_Website_Terms_Help' => 'Idan an cika, dole ne abokan ciniki su amince da waɗannan sharuɗɗa kafin su aika buƙata.',
