'Rental_Theme' => 'Haya',
'Rental_Theme_Needs_Module' => 'yana buƙatar Gudanar da Haya',
'Rental_Theme_Unavailable' => 'Salon Haya yana jera abubuwan Gudanar da Haya naka. Ƙara Gudanar da Haya a shirinka (kuma ka girka sabuntawa ta baya-bayan nan) don amfani da shi.',
'Rental_Theme_Hint' => 'Shafin yanar gizonka yana jera abubuwan Haya › Abubuwa, tare da samuwa da farashi kai tsaye. Masu ziyara suna aika buƙatun ajiya da ke isowa a Haya › Ajiyar wuri.',
