'Bkm_Guide_Website_2_T' => 'Zaɓi lokaci ko aika buƙata',
'Bkm_Guide_Website_2' => 'lokuta a buɗe suna fitowa daga lokutan ma’aikatanka, ranakun hutu da sauran ajiyoyi; buƙata kuma tana bayar da ranar da aka fi so da ɓangaren rana kawai.',
'Bkm_Guide_Website_3_T' => 'Bayanansu',
'Bkm_Guide_Website_3' => 'suna, waya, imel da tambayoyin da nau’in kasuwancinka ke yi.',
'Bkm_Guide_Website_4_T' => 'Jingina',
'Bkm_Guide_Website_4' => 'idan ka nemi ɗaya, suna biyan ta nan take don riƙe lokacin.',
'Bkm_Guide_Website_5_T' => 'Yana jiran ka',
'Bkm_Guide_Website_5' => 'tana shiga Buƙatu a matsayin ana jira, kuma ana riƙe musu lokacin (sai dai idan tabbatarwa kai-tsaye tana kunne).',
'Bkm_Guide_Website_6_T' => 'Shafin ajiyar wurinsu',
'Bkm_Guide_Website_6' => 'suna bibiyar ta daga mahaɗin da ke cikin imel ɗinsu: matsayi, ƙara zuwa kalanda, soke, amsa lokacin da aka ba da shawara.',
'Bkm_Guide_Requests' => 'Amsa buƙatu',
'Bkm_Guide_Requests_1' => 'Buƙatu yana nuna kowace ajiyar wuri da ke jiran ka, wadda riƙewarta ta fi daɗewa a farko, tare da alama a menu.',
'Bkm_Guide_Requests_2' => 'Tabbatar yana zaɓa maka ma’aikaci idan ka bar shi wofi, kuma yana duba ko lokacin har yanzu a buɗe yake.',
'Bkm_Guide_Requests_3' => 'Ba da shawarar wani lokaci idan nasu bai yiwu ba — suna karɓar sa daga shafin ajiyar wurinsu.',
'Bkm_Guide_Requests_4' => 'Ƙi tare da dalili; abokin ciniki zai gan shi.',
'Bkm_Guide_Requests_5' => 'Riƙewar da ta ƙare tana sakin lokacin; ajiyar wurin tana nan har sai ka amsa ta.',
'Bkm_Guide_Day' => 'A ranar',
'Bkm_Guide_Day_1' => 'Duban rana yana nuna ajiyoyin kowane ma’aikaci gefe da gefe.',
'Bkm_Guide_Day_2' => 'Yi alamar ya iso lokacin da abokin ciniki ya shigo.',
'Bkm_Guide_Day_3' => 'Kammala & karɓi kuɗi yana ƙirƙirar siyarwa ta hanyar POS, tare da jingina an riga an ƙidaya ta.',
'Bkm_Guide_Day_4' => 'Kammala ba tare da karɓar kuɗi ba idan an biya ta wata hanya.',
'Bkm_Guide_Day_5' => 'Yi alamar bai zo ba da zarar lokacin farawa ya wuce.',
'Bkm_Guide_Day_6' => 'Dashboard yana nuna jadawalin yau, abin da ke zuwa har yanzu da abin da ba a karɓi kuɗinsa ba tukuna.',
'Bkm_Guide_Deposits' => 'Jingina',
'Bkm_Guide_Deposits_1' => 'Saita adadin a Saitunan ajiyar wuri › Jingina; sabis zai iya samun nasa.',
'Bkm_Guide_Deposits_2' => 'Abokan ciniki suna biya ta masu ba da sabis na biya da aka saita a Shagon yanar gizo › Ƙofar biya, a cikin babban kuɗinka.',
'Bkm_Guide_Deposits_3' => 'Ana riƙe lokacin don biya; ana iya soke ajiyoyin da ba a biya ba kai-tsaye.',
'Bkm_Guide_Deposits_4' => 'Biyan da ya wuce ba tare da abokin ciniki ya dawo shafin ba ana ɗaukar sa kai-tsaye.',
'Bkm_Guide_Deposits_5' => 'Lokacin da ka karɓi kuɗin ajiyar wuri, jingina ita ce biya na farko a kan siyarwar.',
'Bkm_Guide_Deposits_6' => 'Ana mayar da kuɗi a mai ba da sabis na biyanka; sannan ka yi wa jingina alamar an mayar a kan ajiyar wurin.',
'Bkm_Guide_Messages' => 'Imel, WhatsApp da tunatarwa',
'Bkm_Guide_Messages_1' => 'Abokan ciniki suna samun imel lokacin da aka karɓi ajiyar wurinsu, aka tabbatar, aka ƙi, aka canza ko aka soke.',
'Bkm_Guide_Messages_2' => 'Kai kana samun ɗaya don kowace sabuwar ajiyar wuri daga gidan yanar gizo, sokewar abokin ciniki da jinginar da aka biya.',
'Bkm_Guide_Messages_3' => 'Ana aika tunatarwa kafin kowace ziyarar da aka tabbatar (Saitunan ajiyar wuri › Sanarwa).',
'Bkm_Guide_Messages_4' => 'Kunna "Kuma a aika ta WhatsApp" don aika saƙonni iri ɗaya ta can.',
'Bkm_Guide_Messages_5' => 'Ana jera kowane saƙo a kan ajiyar wuri, tare da dalilin da ya sa ba a aika ba idan ba a aika ba.',
'Bkm_Guide_Customers' => 'Abokan ciniki, CRM da tashar abokin ciniki',
'Bkm_Guide_Customers_1' => 'Ana ƙara ajiyar wuri daga gidan yanar gizo zuwa abokan cinikinka; wanda ya sake yin ajiyar wuri da imel da waya iri ɗaya ana gane shi.',
'Bkm_Guide_Customers_2' => 'Idan CRM yana cikin shirinka, ana iya rubuta ajiyoyi a kan abokin ciniki ko lead ɗinsa, kuma buƙatu na iya buɗe yarjejeniya.',
'Bkm_Guide_Customers_3' => 'Abokan ciniki masu asusun tashar abokin ciniki suna ganin ajiyoyinsu a can kuma za su iya soke ko amsa lokacin da aka ba da shawara.',
'Bkm_Guide_Customers_4' => 'Abokan cinikin shago da suka shiga asusunsu suna samun ajiyoyinsu a ƙarƙashin Asusuna.',
'Bkm_Guide_Roles' => 'Wa zai iya yin me',
'Bkm_Guide_Roles_Help' => 'Ba kowace rawa izinin da take buƙata kawai (Saituna › Izinin Rukuni).',
