'Bkm_Guide_Faq' => 'Tambayoyi',
'Bkm_Guide_Faq_1_Q' => 'Me ya sa sabis ba ya bayyana a gidan yanar gizo?',
'Bkm_Guide_Faq_1_A' => 'Yana buƙatar bayanan ajiyar wuri (Ayyuka), "Nuna a gidan yanar gizo" a kunne, kayan yana aiki, kuma — don zaɓar lokaci — wani wanda ake iya yin ajiyar wuri da shi ta yanar gizo kuma yana yin sabis ɗin.',
'Bkm_Guide_Faq_2_Q' => 'Me ya sa babu lokuta a buɗe?',
'Bkm_Guide_Faq_2_A' => 'Duba lokutan aikin ma’aikata, ranakun hutu, hututtuka da hutun da aka amince, lokacin sanarwa da kwanaki nawa a gaba abokan ciniki za su iya yin ajiyar wuri.',
'Bkm_Guide_Faq_3_Q' => 'Shin abokan ciniki biyu za su iya ɗaukar lokaci ɗaya?',
'Bkm_Guide_Faq_3_A' => 'A’a. Ana sake duba lokacin a lokacin da suke yin ajiyar wuri, kuma ajiyar wuri da aka riƙe ko aka tabbatar tana rufe shi. Azuzuwa suna raba kujeru har zuwa iyakarsu.',
'Bkm_Guide_Faq_4_Q' => 'Me ke faruwa idan riƙewa ta ƙare?',
'Bkm_Guide_Faq_4_A' => 'Lokacin yana sake buɗewa ga wasu. Ajiyar wurin tana zama a Buƙatu har sai ka amsa ta (ko a soke ta idan ba a biya jinginarta ba).',
'Bkm_Guide_Faq_5_Q' => 'Shin abokan ciniki suna buƙatar asusu?',
'Bkm_Guide_Faq_5_A' => 'A’a. Suna samun mahaɗi na sirri zuwa shafin ajiyar wurinsu. Asusun shago da na tashar abokin ciniki ma suna jera ajiyoyinsu.',
'Bkm_Guide_Faq_6_Q' => 'Ina kuɗin ke zuwa?',
'Bkm_Guide_Faq_6_A' => 'Jingina tana zuwa ga mai ba da sabis na biyanka; ana karɓar sauran a POS lokacin da ka karɓi kuɗin ajiyar wuri. Rahotanni suna ƙidaya kuɗin shiga daga waɗannan siyarwar.',
'Bkm_Guide_Faq_7_Q' => 'Me ya sa abokin ciniki bai sami imel ba?',
'Bkm_Guide_Faq_7_A' => 'Buɗe ajiyar wurin: jerin saƙonninta yana nuna ko an aika kowane imel, ya gaza ko an tsallake shi, da dalilin.',
'Bkm_Staff_Removed' => 'an cire',
'Bkm_Staff_Not_Bookable' => 'Ba a iya yin ajiyar wuri da shi yanzu',
'Bkm_Requests_Cut' => 'Ana nuna {n} mafi daɗewa. Amsa wasu don ganin sauran, ko ka yi nema.',

