'Mkg_Guide_Audience_Leads' => 'Idan CRM yana kunne, rukuni zai iya nufin masu yiwuwar zama abokan ciniki (leads) na CRM maimakon abokan ciniki (alamomi, tushe, matsayi, maki da sauransu). Ana tsallake masu yiwuwa da suka fita daga jerin, kuma imel zuwa ga masu yiwuwa koyaushe suna ɗauke da hanyar haɗin fita daga jerin.',
