'Mkg_Guide_Faq' => 'Tambayoyi da ake yawan yi',
'Mkg_Guide_Faq_1_Q' => 'Kamfen ɗina yana nan a kan Ana Aikawa kuma babu abin da ke fita.',
'Mkg_Guide_Faq_1_A' => 'Mai aikawa na bayan fage bai ɗauke shi ba. Bayan minti 30 ba tare da ci gaba ba maɓallin Aika Yanzu yana dawowa: danna shi don ci gaba. Idan ya ci gaba da faruwa, nemi mai gudanar da dandalinka ya duba cewa ayyukan bayan fage (queue worker) suna gudana.',
'Mkg_Guide_Faq_2_Q' => 'Masu karɓa suna nuna "An Tsallake: An kashe tashar Imel".',
'Mkg_Guide_Faq_2_A' => 'Kunna "Kunna Imel" a Saitunan Tallatawa, sannan ka sake aika kamfen ɗin.',
'Mkg_Guide_Faq_3_Q' => 'Masu karɓa suna nuna "Ba a saita sabar imel ba".',
'Mkg_Guide_Faq_3_A' => 'Kamfen na imel suna wucewa ta sabar imel ɗinka kawai. Ƙara ta a Saituna > Saitunan Imel.',
'Mkg_Guide_Faq_4_Q' => 'Mutanen da suka karɓi saƙon ba su kai yawan waɗanda ke cikin rukunina ba.',
'Mkg_Guide_Faq_4_A' => 'Ana tsallake abokan ciniki marasa adireshin imel (Imel) ko lambar waya (SMS, WhatsApp). Buɗe kamfen ɗin don ganin wanda aka tsallake da dalili.',
'Mkg_Guide_Faq_5_Q' => 'Shin An Aika yana nufin abokin ciniki ya karɓa?',
'Mkg_Guide_Faq_5_A' => 'An Aika yana nufin sabar imel ɗinka ko gateway ya karɓi saƙon. Ba a bin diddigin isa akwatin saƙo, buɗewa da tace spam.',
'Mkg_Guide_Faq_6_Q' => 'Zan iya gyara kamfen bayan na aika shi?',
'Mkg_Guide_Faq_6_A' => 'A’a. Kamfen da ake aikawa da waɗanda aka aika a kulle suke; ƙirƙiri sabon kamfen maimakon haka.',
'Mkg_Guide_Faq_7_Q' => 'Saƙonnina na WhatsApp ba sa isowa.',
'Mkg_Guide_Faq_7_A' => 'Bayan awa 24 da abokin ciniki ya rubuto maka na ƙarshe, WhatsApp yana isar da samfuran da Meta ya amince da su kawai. Yi amfani da WhatsApp Cloud API ka zaɓi samfurin da aka amince da shi a cikin kamfen.',
'Mkg_Guide_Faq_8_Q' => 'Idan na sake aika kamfen, abokan ciniki za su karɓe shi sau biyu?',
'Mkg_Guide_Faq_8_A' => 'Ci gaba da kamfen da ya makale yana aikawa ne kawai ga masu karɓa da ke Ana Jira, don haka ba za a sake aika saƙo ga wanda aka riga aka kai gare shi ba. Sake aika kamfen da ya kasa yana farawa daga farko da sabon jeri.',

