'Pd_Installments' => 'Kashi-kashi',
'Pd_Single_Payment' => 'Biya sau ɗaya',
'Pd_Guide_How_Title' => 'Yadda yake aiki',
'Pd_Guide_How_Intro' => 'Na’urar POS ita ce na’urar kati ko na’urar rasitin haraji (fiscal cash register) kusa da wurin biya. Stocky yana aika mata adadin, yana jira abokin ciniki ya biya, kuma yana rubuta biyan ne kawai bayan na’urar ta amince.',
'Pd_Guide_Step_1' => 'Ƙara na’urar a nan: model, sito, da hanyar biyan kuɗin da ake rubuta biyan katinta da ita (misali "Credit Card").',
'Pd_Guide_Step_2' => 'Zaɓi yadda Stocky zai kai gare ta: gadar gida a kwamfutar mai karɓar kuɗi, ko cloud API na mai samar maka da sabis. Shigar da ID da makullan daga bankinka ko mai samar maka da sabis.',
'Pd_Guide_Step_3' => 'Danna Gwada haɗi. Dole a gwada na’urorin gada daga kwamfutar mai karɓar kuɗi da gadar ke gudana a kanta.',
'Pd_Guide_Step_4' => 'A POS, zaɓi waccan hanyar biyan kuɗi, danna "Caji a kan na’ura" ka bar abokin ciniki ya biya. Ana iya kammala siyarwar da zarar na’urar ta amince.',
'Pd_Guide_Step_5' => 'Duba Ma’amaloli don biyan kati da aka karɓa ba tare da siyarwa ba (misali, biyan da aka bari a tsakiya) ka soke su ko ka mayar da kuɗin.',
'Pd_Guide_Bridge_Text' => 'Don na’urorin da SDK na kamfanin da ya ƙera su ke sarrafawa a kwamfutar mai karɓar kuɗi (haɗin USB, serial ko LAN). Burauza ba zai iya amfani da SDK kai tsaye ba, don haka ƙaramar manhajar gada tana naɗe shi kuma tana sauraro a wannan kwamfuta.',
'Pd_Guide_Bridge_Point_1' => 'POS yana aika kowace buƙata zuwa URL na gada daga burauzar mai karɓar kuɗi; sabar Stocky ba ta taɓa buƙatar kaiwa ga network na shagonka ba.',
'Pd_Guide_Bridge_Point_2' => 'Ana sa hannu a buƙatu da amsoshi da sirrin haɗin gwiwa, don haka ba za a iya ƙirƙirar amincewa ta ƙarya daga burauza ba.',
'Pd_Guide_Bridge_Point_3' => 'Saka kuma ka kunna gadar a kowace kwamfuta da ke karɓar biyan kati a kan wannan na’ura.',
'Pd_Guide_Cloud_Text' => 'Don masu samar da sabis da ke kaiwa ga na’urar ta intanet. Sabar Stocky ce ke kiran API, don haka babu abin da za a saka a kwamfutar mai karɓar kuɗi.',
'Pd_Guide_Cloud_Point_1' => 'Dole URL na API ya kasance https:// a kan adireshin jama’a.',
'Pd_Guide_Cloud_Point_2' => 'Yayin da abokin ciniki ke biya, Stocky yana tambayar matsayi kowane daƙiƙa 2, don haka endpoint na matsayi ya kamata ya san biyan ta lambarsa; idan API ya amsa kafin katin ya gama ("pending"), tambayar lokaci-lokaci ce ke yanke hukunci.',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'IDE280 na’urar rasitin haraji ce ta sabon zamani (YN ÖKC) tare da mai karanta kati. Galibi ana haɗa ta ta ECR / GMP3 SDK na Ingenico, ko ta sabis ɗin haɗi na bankinka.',
'Pd_Guide_Ide280_Point_1' => 'Haɗa na’urar da kwamfutar mai karɓar kuɗi kamar yadda aka bayyana a takardun Ingenico / banki, sannan ka nuna gadar (ko saitunan API) zuwa gare ta.',
'Pd_Guide_Ide280_Point_2' => 'Ana aika adadin kuɗi duka a matsayin lambobi masu wuraren goma da kuma a kuruş (amount_minor), tare da kuɗin TRY / 949.',
'Pd_Guide_Ide280_Point_3' => 'Da "Cikakken rasitin haraji (fiscal)", kowane kaya yana ɗauke da sashen na’ura na kason VAT ɗinsa — daidaita sassan VAT da yadda aka tsara na’urar.',
'Pd_Guide_Protocol_Title' => 'Yarjejeniyar gada / API',
'Pd_Guide_Protocol_Intro' => 'Stocky yana magana da JSON ga gada ko API. Hanyoyin da ke ƙasa su ne na asali kuma ana iya canza su ga kowace na’ura a ƙarƙashin Na gaba-gaba.',
