'Pd_Guide_When_Sale' => 'Mai karɓar kuɗi ya danna "Caji a kan na’ura". Zai iya amsawa idan katin ya gama, ko nan take da matsayi "pending".',
'Pd_Guide_When_Status' => 'Kowane daƙiƙa 2 yayin da biyan ke jira.',
'Pd_Guide_When_Cancel' => 'Mai karɓar kuɗi ya soke yayin da ake jiran kati.',
'Pd_Guide_When_Void' => 'Soke biya (rana ɗaya, dukan adadin).',
'Pd_Guide_When_Refund' => 'Mayar da wani ɓangare ko dukan biya.',
'Pd_Guide_Request_Title' => 'Buƙata',
'Pd_Guide_Request_Text' => 'Abin da Stocky ke aikawa don siyarwa. Mayar da kuɗi da soke biya suna ɗauke da biyan asali a matsayin "original".',
'Pd_Guide_Response_Title' => 'Amsa',
'Pd_Guide_Response_Text' => 'Ana karanta sunayen filaye cikin sassauci (har ma a ƙarƙashin "data"); "status" ko response_code "00" ne ke yanke sakamako. Ana adana lambobin kati a ɓoye.',
'Pd_Guide_Signing_Title' => 'Sa hannu (gada)',
'Pd_Guide_Signing_Text' => 'Ya kamata gadar ta duba sa hannun Stocky, kuma dole ta sa hannu a ainihin abin da ke cikin amsarta ta kuma maimaita duka "reference" da "operation" — ana ƙin amsoshi marasa sa hannu, ko amsoshi game da wani aiki daban.',
'Pd_Guide_Browser_Title' => 'Damar burauza (gada)',
'Pd_Guide_Browser_Text' => 'Shafin POS yana kiran gadar daga burauza, don haka dole gadar ta amsa da waɗannan CORS headers (har da OPTIONS preflight).',
'Pd_Guide_Safety_Title' => 'Abin da ya kamata a sani',
'Pd_Guide_Safety_1' => 'Ana ajiye siyarwa ne kawai tare da biyan na’ura da aka amince na adadi iri ɗaya; biyan na’ura ɗaya ba zai taɓa biyan siyarwa biyu ba.',
'Pd_Guide_Safety_2' => 'Rufe tagar biya bayan an caji kati yana fara soke wannan cajin.',
'Pd_Guide_Safety_3' => 'Idan na’urar ba ta amsa a kan lokaci ba biyan yana nuna "Babu amsa": duba na’urar, ka soke cajin daga Ma’amaloli idan an caji katin.',
'Pd_Guide_Safety_4' => 'Mayar da kuɗi da soke biya a nan suna motsa kuɗi a kan kati ne kawai; ba sa canza siyarwar. Rubuta kayan da aka dawo da su a Mayar da Sayarwa.',
'Perm_Pos_Terminals_Manage' => 'Na’urorin POS: sarrafawa, mayar da kuɗi da soke biya',
