'Pd_Close_Anyway' => 'Ba a iya soke biya ta katin ba. Rufe duk da haka? Za ta kasance a Na’urorin POS › Ma’amaloli a matsayin "An caja ba tare da siyarwa ba" don a iya soke ta ko a mayar da kuɗin a can.',
