'Ord_Guide_PayAuto_Intro' => 'Wannan ginshiƙi yana nuna nawa aka biya na odar. Yana farawa daga zaɓin da abokin ciniki ya yi a wurin biya, sannan yana sabuntawa da kansa yayin da ake rikodin biya a kan siyarwar da tabbatar da odar ke ƙirƙira. Ba za a iya gyara shi daga wannan shafin ba.',
