'Oc_Identity_Desc' => 'Ana daidaita lambar kaya ta nan da Model da SKU na OpenCart. Ku bar su iri ɗaya a ɓangarorin biyu. Ajiyar kaya ta nan ita ce babbar alƙalumma: ana sabunta shagon daga gare ta bayan kowace oda.',
'Oc_Options_Title' => 'Zaɓuɓɓuka ba tare da nau’ikan ba',
'Oc_Options_Desc' => 'Nau’ikan OpenCart suna da ajiyar kayansu kuma suna daidaita da nau’ikan da ke nan. Kayan da ke da zaɓuɓɓuka kawai, ba tare da an ƙirƙiri nau’ikan ba, ana shigo da shi a matsayin kaya ɗaya kuma ba a raba ajiyar kayansa bisa zaɓi.',
'Oc_Cancel_Title' => 'Odar da aka soke',
'Oc_Cancel_Desc' => 'Soke oda a OpenCart yana juya siyarwarta a nan. Idan an riga an kawo siyarwar ko tana da mayarwa, ba a soke komai: ana yi wa siyarwar alama a cikin bayanan kula da cikin rajistoci don ku duba.',
'Oc_Download_Connector_3' => 'Sauke don OpenCart 3',
'Oc_Opencart3_Title' => 'Shagunan OpenCart 3',
'Oc_Opencart3_Desc' => 'OpenCart 3 ba shi da nau’ikan kansa, sai zaɓuɓɓuka kawai. Kayan da ke da zaɓi ɗaya (misali Size) ana daidaita shi da ajiyar kaya bisa kowace ƙimar zaɓi, wadda take daidaita da nau’ikan da ke nan. Kayan da ke da zaɓuɓɓuka da yawa ana ƙirƙirar zaɓuɓɓukansa ba tare da ajiyar kaya bisa kowane haɗi ba: ana riƙe ajiyar kayansa a kan kayan gaba ɗaya, kuma layukan siyarwarsa suna shigowa a kan kayan.',
'Oc_G_Title' => 'Jagorar OpenCart',
'Oc_G_Open_Settings' => 'Buɗe saitunan OpenCart',
'Oc_G_Your_Setup' => 'Saitinku',
'Oc_G_Your_Setup_Help' => 'Inda wannan wurin aiki yake. Matakan suna sabuntawa yayin da kuke ci gaba.',
'Oc_G_Step_Install' => 'Saka {company} Connector a shagonku',
'Oc_G_Step_Install_Help' => 'Ƙaramin ƙari (extension) da ke ba {company} damar isa ga kayayyaki, ajiyar kaya da oda. OpenCart ba shi da API na waɗannan da kansa.',
'Oc_G_Step_Connect' => 'Haɗa shagon',
'Oc_G_Step_Connect_Help' => 'Liƙa URL na shago da sirrin daga shafin module ɗin a shafin Haɗi, ajiye, sannan ku gudanar da Gwada Haɗin.',
'Oc_G_Step_Connect_Done' => 'An haɗa: connector {connector} a kan OpenCart {opencart}.',
'Oc_G_Step_Enable' => 'Kunna daidaitawa',
'Oc_G_Step_Enable_Help' => 'Babu abin da ke motsi yayin da aka kashe haɗin; ana karɓar webhooks daga shagon amma ana watsi da su.',
'Oc_G_Step_Products' => 'Haɗa kayayyaki',
'Oc_G_Step_Products_Help' => 'Ku jawo kundin kayayyakin shagon ko ku tura naku, ta yadda kowane kaya a ɓangarorin biyu zai kasance an haɗa shi kafin ajiyar kaya ta fara gudana.',
'Oc_G_Step_Products_Done' => 'An haɗa kayayyaki {n} da nau’ikan {v}.',
'Oc_G_Step_Orders' => 'Karɓi oda',
'Oc_G_Step_Orders_Help' => 'Da zarar an haɗa, sabbin oda za su riƙa isowa da kansu. Ku yi odar gwaji a shagon don ganin ta bayyana a ƙarƙashin Siyarwa.',
'Oc_G_Step_Orders_No_Webhook' => 'An shigo da oda, amma har yanzu babu wadda ta iso ta sanarwar shagon. Idan shagon ba zai iya isa wannan adireshin ba, oda za su ci gaba da isowa ta dubawar da ake yi duk bayan ’yan mintuna.',
'Oc_G_Step_Orders_Done' => 'Shagon yana aiko da sanarwar oda.',
'Oc_G_Install_Title' => 'Saka connector',
'Oc_G_Install_Intro' => 'Zaɓi sigar OpenCart ɗinku. Ana saka connector ta mai saka ƙari na OpenCart kansa; ba a gyara kowane fayil da hannu.',
'Oc_G_Opencart_4' => 'OpenCart 4.x',
'Oc_G_Opencart_3' => 'OpenCart 3.x',
'Oc_G_I4_1' => 'Sauke connector don OpenCart 4.',
'Oc_G_I4_2' => 'A fuskar gudanarwar OpenCart ɗinku, buɗe {path}, ɗora fayil ɗin kuma ku danna Install kusa da shi.',
'Oc_G_I4_3' => 'Buɗe {path}, nemo {name} ku danna Install, sannan Edit.',
'Oc_G_I3_1' => 'Sauke connector don OpenCart 3.',
'Oc_G_I3_2' => 'A fuskar gudanarwar OpenCart ɗinku, buɗe {path}, ɗora fayil ɗin kuma ku jira matakan su kammala.',
'Oc_G_I3_3' => 'Buɗe {path}, nemo {name} ku danna Install, sannan Edit.',
'Oc_G_I_4' => 'Shafin module ɗin yana nuna URL na shago da sirri. Ku kwafi duka biyun.',
'Oc_G_I_5' => 'Ku dawo nan, ku liƙa su a shafin Haɗi, ajiye, kuma ku gudanar da {test}. Wannan kuma yana gaya wa shagon inda zai tura sanarwar oda.',
'Oc_G_Requirements' => 'Abin da shagon ke buƙata',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 ko 4.0 zuwa sama, PHP tare da cURL (wanda ke kan kowane mai masauki), da adireshin shago da za a iya isa gare shi daga intanet. Idan shagon yana kan hanyar sadarwa ta sirri, oda za su ci gaba da isowa ta dubawar da ake yi duk bayan ’yan mintuna, muddin wannan wurin aiki zai iya isa ga shagon.',
'Oc_G_First_Title' => 'Daidaitawa ta farko',
'Oc_G_First_Shop_Has' => 'Shagon yana da kundin kayayyaki tuni',
'Oc_G_First_Shop_Has_Text' => 'Ku jawo kayayyaki a shafin Kayayyaki. Ana daidaita kayayyaki ta Model ko SKU da lambobin kayanku kuma ana ƙirƙirar su idan ba su nan; ku zaɓi zaɓin ajiyar kaya don ɗaukar adadin shagon a matsayin ajiyar kaya ta farko.',
'Oc_G_First_Company_Has' => '{company} ne ke da kundin kayayyaki',
'Oc_G_First_Company_Has_Text' => 'Ku tura kayayyaki. Ana ƙirƙirar kayayyakin da ba su nan a shagon tare da ajiyar kayansu; ana haɗa waɗanda ke akwai ta Model ko SKU kuma a sabunta su.',
'Oc_G_First_Both' => 'Ɓangarorin biyu suna da kayayyaki',
'Oc_G_First_Both_Text' => 'Ku fara jawowa, don a haɗa kayayyakin shagon da ke akwai maimakon a maimaita su, sannan ku tura don ƙirƙirar abin da shagon ba shi da shi. Ku bar lambobin kaya da Model iri ɗaya a ɓangarorin biyu.',
'Oc_G_Stock_Master' => '{company} ne ke riƙe da alƙaluman ajiyar kaya',
'Oc_G_Stock_Master_Desc' => 'Bayan daidaitawa ta farko, adadin da ke cikin shagon koyaushe daga {company} ake rubuta shi. Gyara adadi a OpenCart ba shi da tasiri mai ɗorewa: motsi na gaba ko dubawar kowace awa zai share shi.',
'Oc_G_How_Title' => 'Yadda yake aiki',
'Oc_G_T_Products' => 'Kayayyaki',
'Oc_G_Products_1' => 'Ana daidaita kaya ta lambarsa ta nan da Model da SKU na shagon. Ana tuna haɗin, don haka canza sunan kaya daga baya ba zai karya shi ba.',
'Oc_G_Products_2' => 'Idan {company} ya tura kaya yana saita Model, SKU, suna, farashi, matsayi da ajiyar kaya. Ana rubuta bayani, hoto da rukuni ne kawai idan kayan sabo ne a shagon ko ba shi da su, don haka rubutun da aka yi a OpenCart yana nan.',
'Oc_G_Products_3' => 'Kayan da aka ɓoye daga shagon yanar gizo ko wanda ba na siyarwa ba a nan ba a ƙirƙirar shi a shagon; wanda aka riga aka haɗa kuma ana kashe shi a can maimakon haka.',
'Oc_G_T_Variants' => 'Nau’ikan da zaɓuɓɓuka',
'Oc_G_Variants_4' => 'OpenCart 4 yana da nau’ikan na gaske (kaya mai zaɓin Color da Size), kowanne da ajiyar kayansa. Suna daidaita da nau’ikanku ta ɓangarorin biyu, kuma ana daidaita kowanne ta Model ɗinsa.',
'Oc_G_Variants_3' => 'OpenCart 3 ba shi da nau’ikan, sai zaɓuɓɓuka kawai, da ajiyar kaya bisa kowace ƙimar zaɓi. Kayan da ke da zaɓi ɗaya (misali Size) ana daidaita shi da ajiyar kaya bisa kowace ƙima, wadda take daidaita da nau’ikanku. Kayan da ke da zaɓuɓɓuka da yawa ana ƙirƙirar zaɓuɓɓukansa ba tare da ajiyar kaya bisa kowane haɗi ba: ajiyar kayansa tana kan kayan gaba ɗaya, kuma layukan siyarwarsa suna shigowa a kan kayan.',
'Oc_G_Variants_Multi' => 'Kayan shago da ke da zaɓuɓɓuka kawai, ba tare da an ƙirƙiri nau’ikan ba, ana shigo da shi a matsayin kaya ɗaya; ana rubuta hakan a cikin rajistoci.',
'Oc_G_T_Stock' => 'Ajiyar kaya',
'Oc_G_Stock_1' => 'Idan maɓallin ajiyar kaya a kunne yake, kowane motsi a nan (siyarwa, mayarwa, siyan kaya, daidaitawa, canja wuri) yana sabunta shagon cikin daƙiƙoƙi, bayan shafin ya amsa, don haka mai karɓar kuɗi ba ya jiran shagon.',
'Oc_G_Stock_2' => 'Sau ɗaya a kowace awa ana duba kowane kaya da aka haɗa a gyara shi, wanda ke rufe manyan canje-canjen da turawa nan take ba ta gani. Shafin Ajiyar kaya yana tura komai a duk lokacin da kuke so.',
'Oc_G_Stock_3' => 'Ayyuka (sabis), kayayyakin da aka yi wa alama koyaushe akwai su, da combo waɗanda abubuwan cikinsu ba su da iyaka ana nuna su a matsayin koyaushe akwai a shagon. Zaɓi sito a shafin Haɗi don ƙidaya wannan sito kawai; in ba haka ba ana haɗa dukkan sitoci.',
'Oc_G_T_Orders' => 'Oda da matsayi',
'Oc_G_Orders_1' => 'Shagon yana sanar da sabuwar oda ko wadda aka canza nan take kuma ana sake karanta ta ta hanyar haɗin da aka sa hannu, don haka ba a amince da komai a cikin sanarwar kanta. Duk bayan ’yan mintuna, dubawa tana jawo duk abin da sanarwa ta tsallake. Kowace oda tana zama siyarwa ɗaya mai lamba OC-<order number>; ana daidaita abokin ciniki ta imel ko a ƙirƙira shi.',
'Oc_G_Col_List' => 'Jerin matsayi',
'Oc_G_Col_Meaning' => 'Abin da yake yi a nan',
'Oc_G_Col_Default' => 'An saita daga shagonku',
'Oc_G_Default_Commit' => 'Matsayin da ke rage ajiyar kaya a OpenCart (Pending, Processing, Shipped, Complete a tsoho)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'Ana cike jerin daga shagonku a haɗi na farko kuma ana iya canza su a shafin Haɗi. Ku bar jerin farko daidai da matsayin da ke rage ajiyar kaya a OpenCart, don ɓangarorin biyu su motsa ajiyar kaya a mataki ɗaya.',
'Oc_G_Orders_3' => 'Odar da ke da abin da bai dace da kowane kaya ba ana riƙe ta, kuma ana shigo da kayan daga shagon idan yana can. Ana sake gwada odar da aka riƙe a kowace dubawa da aka tsara; bayan gwaji goma sha biyu ana rubuta su a rajista a bar muku su don ku jawo da hannu.',
'Oc_G_T_Cancel' => 'Sokewa da mayar da kuɗi',
'Oc_G_Cancel_1' => 'Idan oda ta kai matsayin an soke a shagon, ana juya siyarwarta a nan: ajiyar kaya tana dawowa, ana cire biyan kuɗinta kuma ana goge siyarwar, daidai kamar yadda goge ta a shafin Siyarwa zai yi.',
'Oc_G_Cancel_2' => 'Siyarwar da aka riga aka kawo, mai mayarwa, ko wadda hukumar haraji ta karɓa, shagon ba ya taɓa juya ta. Ana yi mata alama a cikin bayanan kula da cikin rajistoci don ku duba.',
'Oc_G_Cancel_3' => 'Idan aka dawo da odar a shagon daga baya, za ta sake shigowa a matsayin sabuwar siyarwa.',
'Oc_G_T_Automation' => 'Maɓallan aiki da kai',
'Oc_G_Auto_1' => 'Shigo da oda kai tsaye: sanarwar oda da dubawar da aka tsara. Idan a kashe yake, oda suna isowa ne kawai idan kun jawo su a shafin Oda.',
'Oc_G_Auto_2' => 'Tura ajiyar kaya kai tsaye: sabunta ajiyar kaya nan take da dubawar kowace awa. Idan a kashe yake, shagon yana canzawa ne kawai idan kun tura ajiyar kaya da hannu.',
'Oc_G_Auto_3' => 'Tura canje-canjen kaya kai tsaye: kayan da aka ƙirƙira ko aka gyara a nan yana sabunta shagon nan take. Idan a kashe yake, yi amfani da shafin Kayayyaki.',
'Oc_G_T_Faq' => 'Tambayoyi',
'Oc_G_Q_Secret' => 'Gwada Haɗin ya ce sirrin bai dace ba',
'Oc_G_A_Secret' => 'Buɗe module ɗin {company} Connector a OpenCart ku sake kwafin sirrin; module da aka sake sakawa yana samun sabo. Liƙa shi a shafin Haɗi ku ajiye kafin gwadawa.',
'Oc_G_Q_Clock' => 'Gwada Haɗin ya ce agogon shagon ya yi nisa sosai',
'Oc_G_A_Clock' => 'Buƙatun da aka sa hannu suna ɗauke da lokaci kuma ana ƙin su idan agogunan biyu sun bambanta da fiye da mintuna biyar. Saita kwanan wata da lokaci a sabar shagon.',
'Oc_G_Q_Redirect' => 'Gwada Haɗin ya ce shagon yana karkatarwa zuwa wani adireshi',
'Oc_G_A_Redirect' => 'Shagonku yana amsa a wani adireshi daban, yawanci https maimakon http ko tare da www. Yi amfani da adireshin da aka nuna a saƙon a matsayin URL na shago.',
'Oc_G_Q_Not_Answering' => 'Gwada Haɗin ya ce connector bai amsa ba',
'Oc_G_A_Not_Answering' => 'Adireshin ba shagon OpenCart ba ne, ko ba a saka module ɗin ba ko an kashe shi. Duba URL na shago, sannan ku tabbatar {company} Connector yana nuna an saka shi kuma an kunna shi a ƙarƙashin Extensions → Modules.',
'Oc_G_Q_No_Orders' => 'Ana yin oda a shagon amma suna ɗaukar mintuna kafin su bayyana',
'Oc_G_A_No_Orders' => 'Shagon ba zai iya isa wannan wurin aiki ba, don haka oda suna isowa ne kawai ta dubawar da aka tsara. Duba adireshin {company} a shafin module ɗin: dole ne sabar shagon ta iya isa gare shi. Gudanar da Gwada Haɗin yana sake yin rajistarsa.',
'Oc_G_Q_Stock_Wrong' => 'Adadi a cikin shagon ba daidai ba ne',
'Oc_G_A_Stock_Wrong' => 'Ku tura ajiyar kaya a shafin Ajiyar kaya, wanda ke sake rubuta kowane kaya da aka haɗa daga alƙaluman da ke nan. Idan ya ci gaba da kaucewa, duba cewa maɓallin ajiyar kaya a kunne yake kuma babu wanda ke gyara adadi a OpenCart.',
'Oc_G_Q_Out_Of_Stock' => 'Kaya yana nuna ya ƙare a shagon duk da cewa akwai ajiyar kaya a nan',
'Oc_G_A_Out_Of_Stock' => 'A OpenCart 3, kayan da ke da zaɓuɓɓuka da yawa yana riƙe ajiyar kayansa a kan kayan gaba ɗaya; duba adadin kayan a shagon maimakon zaɓuɓɓukansa. Ga kowane kaya, ku tura ajiyar kaya sau ɗaya ku duba rajistoci na wannan kayan.',
'Oc_G_Q_Held' => 'Rajistoci sun ce an riƙe wata oda',
'Oc_G_A_Held' => 'Ɗaya daga cikin abubuwanta bai dace da kowane kaya a nan ba kuma ba a iya shigo da shi daga shagon ba, yawanci saboda an goge kayan a can. Ƙirƙiri ko haɗa kayan, sannan ku jawo oda a shafin Oda.',
'Oc_G_Q_Deleted_Sale' => 'Na goge siyarwar da aka shigo da ita kuma ta dawo',
'Oc_G_A_Deleted_Sale' => 'Muddin odar tana nan a shagon, sanarwa ko dubawa ta gaba za ta sake shigo da ita. Maimakon haka ku soke odar a shagon, wanda zai juya siyarwar a nan.',
'Oc_G_Q_Uninstall' => 'Ta yaya zan cire haɗin shagon?',
'Oc_G_A_Uninstall' => 'Kashe daidaitawa a shafin Haɗi; babu abin da ke motsi yayin da a kashe yake. Don cire haɗin daga shagon, cire {company} Connector a ƙarƙashin Extensions → Modules.',
'Oc_Full_Guide' => 'Buɗe cikakken jagora',
'Comm_Receipt_Account_Hint' => 'Asusun kuɗi ko na banki da wannan biyan ke fita daga ciki. Sauransa yana raguwa da adadin kuma littafin lissafi yana rubuta Sales Commission Expense a kansa.',
'Comm_G_Q_Ledger' => 'Me biyan kwamisho ke yi a cikin lissafi?',
'Comm_G_A_Ledger' => 'Idan kuka ƙirƙiri rasidi kuka zaɓi asusu, saura na wannan asusu yana raguwa da adadin rasidin kuma, idan rubutun lissafi na atomatik a kunne suke, ana rubuta rubutun lissafi: debit Kuɗaɗen Fita na Kwamishon Siyarwa (Sales Commission Expense, 5200-COMM), credit asusun kuɗi ko na banki da aka zaɓa. Idan ba a zaɓi asusu ba, credit ɗin yana faɗawa asusun Kuɗi na tsoho (Cash) kuma babu sauran da ke canzawa.',
'Hide_Zero_Decimals' => 'Ɓoye Ɗigon Sifili',
'Sys_Hide_Zero_Decimals_Help' => 'Nuna adadi cikakku ba tare da ɗigonsu ba: 100.00 ya zama 100, yayin da 100.50 ke riƙe ɗigonsa. Don nunawa kawai; ƙimomin da aka adana da lissafi ba sa canzawa.',
'Sys_Currency_Position_Before_NoSpace' => 'Kafin adadin, ba tazara',
'Sys_Currency_Position_After_NoSpace' => 'Bayan adadin, ba tazara',
'Supplier_Wallet' => 'Walat ɗin Mai Kaya',
'Supplier_Wallets' => 'Walat ɗin Masu Kaya',
'Supplier_Ledger' => 'Littafin Lissafin Mai Kaya',
'Sys_Supplier_Wallet_Help' => 'Riƙe sauran kuɗin da aka riga aka biya wa masu kaya: ƙarin kuɗi, kiredit na mayarwa, da biyan siyan kaya daga walat. Yana buƙatar fasalin shiri na Walat ɗin Mai Kaya.',
'SW_Allow_Negative' => 'Bari saura na walat ya zama ƙasa da sifili',
'Sys_SW_Allow_Negative_Help' => 'Bari biyan siyan kaya ya wuce sauran walat ɗin mai kaya maimakon a ƙi shi.',
'SW_Wallet_Balance' => 'Sauran Walat',
'SW_Net_After_Wallet' => 'Saura Bayan Walat',
'SW_Balance_After' => 'Saura Bayan',
