'SW_Wallet_Moves' => 'Motsin Walat',
'SW_Total_Advances' => 'Jimillar Kuɗin Gaba',
'SW_Overdrawn' => 'Ya Wuce Saura',
'SW_Wallets_Count' => 'Walat',
'SW_Frozen_Count' => 'Walat da Aka Daskare',
'SW_Frozen' => 'An Daskare',
'SW_Freeze' => 'Daskare Walat',
'SW_Unfreeze' => 'Cire Daskarewar Walat',
'SW_Freeze_Confirm' => 'Walat da aka daskare yana ƙin kowane motsi har sai an cire daskarewarsa. A ci gaba?',
'SW_Unfreeze_Confirm' => 'A sake barin motsin walat ga wannan mai kaya?',
'SW_Only_With_Balance' => 'Walat masu saura kawai',
'SW_Top_Up' => 'Ƙara Kuɗi',
'SW_Refund' => 'Mayar da Kuɗi daga Walat',
'SW_Adjust' => 'Daidaita Saura',
'SW_Top_Up_Help' => 'Kuɗin da aka biya wa mai kaya tun gaba. Yana fita daga asusun da aka zaɓa kuma ana riƙe shi a walat har sai an kashe shi wajen siyan kaya.',
'SW_Refund_Help' => 'Mai kaya yana mayar da wani ɓangare na kuɗin gaba a tsabar kuɗi. Adadin yana fita daga walat kuma yana shiga asusun da aka zaɓa.',
'SW_Adjust_Help' => 'Gyara da hannu ba tare da motsin kuɗi ba. Ana buƙatar dalili kuma ana riƙe shi a littafin lissafi.',
'SW_Adjust_Credit' => 'Ƙara a walat',
'SW_Adjust_Debit' => 'Cire daga walat',
'SW_Pay_From_Wallet' => 'Biya daga walat ɗin mai kaya',
'SW_Pay_From_Wallet_Help' => 'Ana ɗaukar adadin daga sauran kuɗin da aka riga aka biya wa wannan mai kaya. Ba a buƙatar asusu ko hanyar biya.',
'SW_Credit_To_Wallet' => 'Kiredit zuwa walat ɗin mai kaya',
'SW_Credit_To_Wallet_Help' => 'Maimakon tsabar kuɗi, mai kaya yana daidaita wannan mayarwa a matsayin kiredit na walat da za ku iya kashewa a siyan kaya na gaba.',
'SW_Disabled_Hint' => 'An kashe Walat ɗin Mai Kaya. Kunna shi a ƙarƙashin Saitunan Tsari > Fasali (yana kuma buƙatar fasalin shiri na Walat ɗin Mai Kaya).',
'SW_Src_top_up' => 'Ƙarin kuɗi',
'SW_Src_refund' => 'Mayar da kuɗi',
'SW_Src_adjustment' => 'Daidaitawa',
'SW_Src_purchase_payment' => 'Biyan siyan kaya',
'SW_Src_return_credit' => 'Kiredit na mayarwa',
