'SW_Src_reversal' => 'Juyawa',
'SW_Err_wallet_disabled' => 'Ba a kunna walat ɗin mai kaya ba.',
'SW_Err_wallet_frozen' => 'An daskare walat ɗin wannan mai kaya.',
'SW_Err_wallet_insufficient_balance' => 'Sauran walat bai isa ba.',
'SW_Err_wallet_invalid_amount' => 'Dole ne adadin ya fi sifili.',
'SW_Perm_View' => 'Walat ɗin mai kaya: duba',
'SW_Perm_Manage' => 'Walat ɗin mai kaya: gudanarwa',
'SW_Top_Ups_Total' => 'Ƙarin Kuɗi (Jimilla)',
'SW_Spent_Total' => 'Abin da Aka Kashe daga Walat',
'Purchases_Grand' => 'Siyan Kaya (Jimilla)',
'Purchases_Paid' => 'Siyan Kaya (An Biya)',
