'Oc_Code_Source' => 'Tushen lambar kaya',
'Oc_Code_Source_Help' => 'Wane filin OpenCart ne lambar kaya a nan. Model dole ne a OpenCart, don haka wasu shaguna suna rubuta rukuni ko nau’in kaya a ciki kuma su riƙe ainihin lambar kaya a SKU, ISBN, UPC, EAN, JAN ko MPN; zaɓi wannan filin ga irin wannan shago. Ana amfani da Model, sannan SKU, idan filin da aka zaɓa babu komai. Yana aiki kan kayayyakin da aka jawo, daidaitawa da turawa.',
