'Oc_Connector_Link' => 'Gidan yanar gizon connector',
'Oc_Connector_Link_Help' => 'Adireshin gidan yanar gizonku. OpenCart yana haɗa sunan connector da shi a shafin Extensions > Installer. Bar shi babu komai don amfani da adireshin wannan wurin aiki na {company}.',
'Store_Warehouses_Help' => 'Ajiyar kaya da ake nunawa da ake cirewa ta kan layi tana fitowa daga waɗannan sitoci. Yayin da "Taƙaita kayayyaki bisa sito" ke a kunne a Fasali, shagon kuma yana jera kayayyakin da ke na (ko ke da ajiyar kaya a) waɗannan sitoci kawai.',
'Oc_Code_Source_Needs_Update' => 'Connector da aka saka a shagon (sigar {version}) yana ba da rahoton Model da SKU kawai. Sake sauke connector ku ɗora shi a kan tsohon a shagon don a karanta wannan filin.',
'Oc_L_Title' => 'Rajistocin OpenCart',
