'Oc_L_H_Secret' => 'Sirrin da aka ajiye a nan ba shi ne wanda module ɗin connector a OpenCart ke da shi ba, don haka shagon yana ƙin kowane kira.',
'Oc_L_F_Secret' => 'A OpenCart buɗe Extensions → Modules → connector ɗin, ku kwafi sirrin da aka nuna a can, ku liƙa shi a shafin Haɗi ku ajiye. Sake saka module ɗin yana ƙirƙirar sabon sirri.',
'Oc_L_H_Clock' => 'Agogon sabar OpenCart ya bambanta sosai da namu, don haka buƙatun da aka sa hannu suna kamar sun ƙare.',
'Oc_L_F_Clock' => 'Ku roƙi mai ba ku masauki ya saita lokacin sabar (NTP). Bambancin ’yan mintuna kawai ya isa ya hana haɗin.',
'Oc_L_H_Disabled' => 'An saka module ɗin connector a OpenCart amma an kashe shi.',
'Oc_L_F_Disabled' => 'A OpenCart buɗe Extensions → Modules → connector ɗin ku saita Status zuwa Enabled.',
'Oc_L_H_Unreachable' => 'Shagon bai amsa a adireshin da aka ajiye ba, ko ba a saka module ɗin connector a can ba.',
'Oc_L_F_Unreachable' => 'Buɗe URL na shago a burauza don duba yana kan layi, tabbatar an saka module ɗin connector kuma an kunna shi, kuma ku duba cewa babu firewall ko yanayin gyara (maintenance mode) da ke toshe sabarmu.',
'Oc_L_H_Redirect' => 'Shagon yana tura baƙi zuwa wani adireshi (misali daga http zuwa https ko zuwa www).',
'Oc_L_F_Redirect' => 'Ajiye adireshin da aka ambata a saƙon a matsayin URL na shago a shafin Haɗi.',
'Oc_L_H_Not_Configured' => 'URL na shago ko sirrin ya ɓace, don haka ba za a iya aika komai ba tukuna.',
'Oc_L_F_Not_Configured' => 'Cike URL na shago da sirrin a shafin Haɗi, ajiye kuma ku gudanar da Gwada Haɗin.',
'Oc_L_H_Model_Taken' => 'Kayan da aka tura zuwa shagon yana da lambar da wani kayan shago, ko ɗaya daga cikin nau’ikansa, ke amfani da ita tuni a matsayin Model ɗinsa.',
'Oc_L_F_Model_Taken' => 'Canza lambar ɗaya daga cikin kayayyakin biyu, ko ku fara jawo kayayyaki don a haɗa kayan shagon da ke akwai maimakon a sake ƙirƙira shi.',
'Oc_L_H_Model_Missing' => 'Kayan da aka tura zuwa shagon ba shi da lamba ko suna. OpenCart yana buƙatar duka biyun.',
'Oc_L_F_Model_Missing' => 'Ba kayan lamba da suna a nan, sannan ku sake turawa.',
'Oc_L_H_Held' => 'An karɓi oda amma wasu daga cikin abubuwanta ba su dace da kowane kaya a nan ba, don haka tana jira kuma ba a ƙirƙiri siyarwa ba.',
'Oc_L_F_Held' => 'Ƙirƙiri ko jawo kayayyakin da suka ɓace (an jera abubuwan a ƙasa), sannan ku sake jawo oda. Ana sake gwada odar da aka riƙe kai tsaye sau kaɗan.',
'Oc_L_H_Given_Up' => 'Ba a iya shigo da wata oda ba bayan gwaji da yawa kuma ba a ƙara gwada ta.',
'Oc_L_F_Given_Up' => 'Tabbatar kayayyakinta suna nan, sannan ku jawo oda da hannu daga shafin Oda tare da kwanan wata kafin odar.',
'Oc_L_H_Review' => 'An soke wata oda a OpenCart bayan an kawo siyarwar a nan ko an mayar da ita, don haka ba a juya ajiyar kaya kai tsaye ba.',
'Oc_L_F_Review' => 'Buɗe siyarwar ku yanke shawara ko za ku mayar da abubuwan ko ku bar ta yadda take.',
'Oc_L_H_Reversed' => 'An soke wata oda a OpenCart kuma an juya siyarwar da ta dace da ita a nan, an mayar da ajiyar kayanta.',
'Oc_L_H_Backlog' => 'Jawo oda da aka tsara ya sami oda fiye da waɗanda yake sarrafawa a zagaye ɗaya kuma zai sake farawa a gaba.',
'Oc_L_F_Backlog' => 'Jawo oda da hannu daga shafin Oda don share tarin.',
'Oc_L_H_Paused' => 'An dakatar da turawa ta atomatik na ɗan lokaci saboda shagon ya daina amsawa. Canje-canjen da aka yi a lokacin za a aika su da zarar ya sake amsawa.',
'Oc_L_F_Paused' => 'Duba cewa shagon yana kan layi. Ba a buƙatar wani abu kuma; layin jira yana ci gaba da kansa.',
'Oc_L_H_Busy' => 'Turawa biyu ta atomatik sun zo lokaci ɗaya kuma ɗaya ta ja da baya. Babu abin da ya ɓace.',
'Oc_L_H_Codes_Suffixed' => 'Wasu kayayyakin da aka jawo suna ɗauke da lambar da wani kayan shago ya riga ya samu a nan, yawanci saboda filin lambar da aka zaɓa babu komai ko yana ɗauke da sunan rukuni. An ƙirƙira su da id na OpenCart a haɗe don kada kayayyaki biyu su haɗu.',
'Oc_L_F_Codes_Suffixed' => 'Cike filin lamba (Model, SKU, ISBN…) a OpenCart ga kayayyakin da aka jera a ƙasa, ko ku zaɓi wani Tushen lambar kaya a shafin Haɗi, sannan ku sake saita haɗin kayayyaki ku sake jawowa.',
'Oc_L_H_Options' => 'Wasu kayayyakin shago suna da zaɓuɓɓuka (girma, launi…) ba tare da ajiyar kaya ta nau’i ba, don haka ana bin ajiyar kaya ga kayan gaba ɗaya.',
'Oc_L_F_Options' => 'Ba a buƙatar komai. Don bin ajiyar kaya bisa kowane zaɓi, mayar da waɗannan zaɓuɓɓuka nau’ikan a OpenCart 4, ko ku yi amfani da zaɓi ɗaya kowane kaya a OpenCart 3.',
'Oc_L_H_Pull_Ok' => 'An karanta wannan shafin kayayyaki daga shagon. An ƙirƙira yana nufin sabon kaya a nan; an sabunta yana nufin ya riga ya kasance kuma an haɗa shi.',
'Oc_L_H_Pull_Failed' => 'Ba a iya ajiye wasu kayayyaki a wannan shafin a nan ba; an jera kowanne a ƙasa tare da dalilin.',
'Oc_L_F_Pull_Failed' => 'Gyara kayayyakin da aka jera a OpenCart (rashin suna ko lamba ne dalilin da aka saba) ku sake jawowa. Waɗanda suka gaza kaɗai abin ya shafa.',
'Oc_L_H_Push_Warnings' => 'An aika kayayyaki zuwa shagon, amma shagon ya ba da rahoton matsaloli da wasunsu, kamar hoton da bai iya saukewa ba.',
'Oc_L_F_Push_Warnings' => 'Karanta jerin da ke ƙasa. Dole ne sabar shagon ta iya isa ga hotuna; duk sauran an ajiye su yadda aka aika.',
'Oc_L_H_Missing_Remote' => 'An tura ajiyar kaya, amma wasu kayayyakin da aka haɗa ba su nan a shagon yanzu.',
'Oc_L_F_Missing_Remote' => 'Tura kayayyaki don sake ƙirƙirar su a shagon, ko ku sake saita haɗin kayayyaki idan an goge su da gangan.',
'Oc_L_H_Generic' => 'Wani mataki na daidaitawa ya gaza. Saƙon da ke sama shi ne dalilin shagon ko na sabar kanta.',
'Oc_L_F_Generic' => 'Gudanar da Gwada Haɗin a shafin Haɗi. Idan ya yi nasara, sake gwada matakin; idan ya gaza, bi shawarar da ya bayar.',
'Oc_L_H_Code_Fallback' => 'Wasu kayayyaki a wannan shafin sun iso ba tare da ƙima a filin da aka zaɓa a matsayin Tushen lambar kaya ba, don haka aka yi amfani da Model ɗinsu (sau da yawa sunan rukuni) a matsayin lamba.',
'Oc_L_F_Code_Fallback' => 'Duba "Kayayyakin da ke ɗauke da kowane fili" a ƙasa. Idan filin da aka zaɓa yana nuna 0 alhali shagon yana da waɗannan ƙimomi, shagon yana riƙe su ƙarƙashin wani sunan mai ganewa daban; buɗe ɗaya daga cikin kayayyakin da aka jera a OpenCart (Data tab, Product Codes) ku aiko mana da abin da yake nunawa. In ba haka ba, cike filin a OpenCart ga kayayyakin da aka jera ku sake jawowa.',
'Oc_L_H_Old_Connector' => 'Shagon har yanzu yana amfani da connector da ya girmi 1.1.0, wanda ke aika Model da SKU kawai, don haka filin lambar da aka zaɓa ba ya taɓa isowa kuma aka yi amfani da Model.',
'Oc_L_F_Old_Connector' => 'Sake sauke connector, ku cire ku goge tsohon a OpenCart (Extensions → Installer), ku saka sabon, ku liƙa sabon sirrinsa a shafin Haɗi ku gudanar da Gwada Haɗin. Dole ne shafin ya nuna Connector 1.1.0 kafin ku jawo.',
