'LicK_G_Request_Help' => 'Aika JSON body tare da license_key. product (lambar kaya) ba dole ba ne kuma yana tabbatar da cewa maɓallin na kayanku ne. Aika domain ko device_id (+ device_name idan ana so) — ana buƙatar su ga lasisin da aka kulle da kuma lasisin da ke da iyakar kunnawa. Aika nonce na bazata tare da kowane kira kuma ku duba ya dawo a cikin token.',
